const fs = require('fs');
const data = JSON.parse(fs.readFileSync('eslint_report.json', 'utf8'));

const errors = {};
let totalErrors = 0;

data.forEach(file => {
  file.messages.forEach(msg => {
    if (msg.severity === 2) { // 2 means error
      totalErrors++;
      const rule = msg.ruleId || 'fatal-error';
      if (!errors[rule]) errors[rule] = 0;
      errors[rule]++;
    }
  });
});

console.log('Total errors:', totalErrors);
console.log('Errors breakdown:');
console.table(errors);

import fs from 'fs';
import path from 'path';

const analysis = JSON.parse(fs.readFileSync('/tmp/analysis.json', 'utf8'));

// We want to find templates that are currently NOT complete, but HAVE SOME components (not just unworked skeletons)
const content = fs.readFileSync('./src/data/templates.js', 'utf8');

// Get all complete ids (from our previous check, there are 43)
const completeIds = new Set();
const blocks = content.split('  },');
blocks.forEach(block => {
  if (block.includes('isComplete: true')) {
    const idMatch = block.match(/id:\s*["']([^"']+)["']/);
    if (idMatch) completeIds.add(idMatch[1]);
  }
});

const partialsToFinish = analysis.filter(a => {
  // If it's already complete, we assume it's done (or should we check if it has missing sections?)
  if (completeIds.has(a.id)) {
     if (a.missingSections) return true;
     return false;
  }

  // If it's incomplete
  // If it has multiple files, it's partially worked on
  if (a.files.length > 2) return true;

  return false;
});

console.log(partialsToFinish.map(a => a.id));

import fs from 'fs';
import path from 'path';

const analysis = JSON.parse(fs.readFileSync('/tmp/analysis.json', 'utf8'));

// Filter for strictly partial ones:
const strictlyPartial = analysis.filter(a => {
  // It has files
  if (a.files.length < 3) return false; // if it only has index.jsx and maybe one other, it's unworked or monolithic

  const hasHeroOrAbout = a.files.includes('Hero.jsx') || a.files.includes('About.jsx') || a.files.includes('AboutSection.jsx');
  const hasExperienceOrSkills = a.files.includes('Experience.jsx') || a.files.includes('Skills.jsx') || a.files.includes('SkillsSection.jsx');

  // It MUST have Hero/About (meaning someone started styling it)
  // But it MUST be missing Experience/Skills (meaning it's not finished)
  return hasHeroOrAbout && !hasExperienceOrSkills;
});

console.log('Strictly partial count:', strictlyPartial.length);
console.log(strictlyPartial.map(a => a.id));

import fs from 'fs';
