import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Plus, FileText, Briefcase, Search, Mic } from "lucide-react";
import { useNavigate } from "react-router-dom";

export default function FAB({ scrollContainerRef }) {
  const [isOpen, setIsOpen] = useState(false);
  const [isVisible, setIsVisible] = useState(true);
  const navigate = useNavigate();

  const actions = [
    {
      label: "Create Portfolio",
      icon: <FileText size={18} />,
      onClick: () => navigate("/portfolio"),
    },
    {
      label: "Upload Resume",
      icon: <Briefcase size={18} />,
      onClick: () => navigate("/upload"),
    },
    {
      label: "Search Jobs",
      icon: <Search size={18} />,
      onClick: () => navigate("/jobs"),
    },
    {
      label: "Start Interview",
      icon: <Mic size={18} />,
      onClick: () => navigate("/interview"),
    },
  ];

  useEffect(() => {
    let lastScrollY = 0;
    const mainContainer = scrollContainerRef?.current;

    const handleScroll = () => {
      if (!mainContainer) return;

      const currentScrollY = mainContainer.scrollTop;

      setIsVisible(
        currentScrollY < lastScrollY || currentScrollY < 100
      );

      lastScrollY = currentScrollY;
    };

    mainContainer?.addEventListener("scroll", handleScroll);

    return () => {
      mainContainer?.removeEventListener("scroll", handleScroll);
    };
  }, [scrollContainerRef]);

  // Close menu when FAB becomes hidden
  useEffect(() => {
    if (!isVisible && isOpen) {
      setIsOpen(false);
    }
  }, [isVisible, isOpen]);

  // Escape key closes menu
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === "Escape" && isOpen) {
        setIsOpen(false);
      }
    };

    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [isOpen]);

  return (
    <motion.div className="fixed bottom-6 right-6 z-50">
      <AnimatePresence>
        {isVisible && (
          <div className="flex flex-col-reverse items-end gap-3">
            <motion.button
              type="button"
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              exit={{ scale: 0 }}
              onClick={() => setIsOpen(!isOpen)}
              aria-label={
                isOpen ? "Close quick actions" : "Open quick actions"
              }
              aria-expanded={isOpen}
              className="p-4 bg-primary text-primary-foreground rounded-full shadow-xl hover:scale-110 transition-transform glow"
            >
              <motion.div animate={{ rotate: isOpen ? 45 : 0 }}>
                <Plus size={24} />
              </motion.div>
            </motion.button>

            {isOpen && (
              <motion.div
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                className="flex flex-col gap-2 mb-2"
                role="menu"
                aria-label="Quick actions"
              >
                {actions.map((action, index) => (
                  <button
                    key={index}
                    type="button"
                    role="menuitem"
                    tabIndex={0}
                    aria-label={action.label}
                    onClick={() => action.onClick?.()}
                    className="flex items-center gap-3 px-4 py-2 glass border-border rounded-full shadow-lg hover:bg-primary/10 hover:text-primary transition-all-300 hover:-translate-y-1 whitespace-nowrap"
                  >
                    {action.icon}
                    <span className="text-sm font-medium">
                      {action.label}
                    </span>
                  </button>
                ))}
              </motion.div>
            )}
          </div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Bell, MapPin, DollarSign, Briefcase, Tag } from 'lucide-react';
import toast from 'react-hot-toast';
import { jobAlertsApi } from '../services/api';

const EMPLOYMENT_TYPES = [
    { value: 'full-time', label: 'Full-time' },
    { value: 'part-time', label: 'Part-time' },
    { value: 'contract', label: 'Contract' },
    { value: 'internship', label: 'Internship' }
];

export default function JobAlertModal({ isOpen, onClose, onSuccess, editAlert = null }) {
    const [loading, setLoading] = useState(false);
    const [formData, setFormData] = useState({
        title: editAlert?.title || '',
        keywords: editAlert?.keywords?.join(', ') || '',
        location: editAlert?.location || '',
        remoteOnly: editAlert?.remoteOnly || false,
        salaryMin: editAlert?.salaryMin || '',
        salaryMax: editAlert?.salaryMax || '',
        employmentType: editAlert?.employmentType || ['full-time']
    });

    useEffect(() => {
        setFormData({
            title: editAlert?.title || '',
            keywords: editAlert?.keywords?.join(', ') || '',
            location: editAlert?.location || '',
            remoteOnly: editAlert?.remoteOnly || false,
            salaryMin: editAlert?.salaryMin || '',
            salaryMax: editAlert?.salaryMax || '',
            employmentType: editAlert?.employmentType || ['full-time']
        });
    }, [editAlert]);

    const parseSalary = (value) => {
        const trimmed = String(value ?? '').trim();
        if (!trimmed) return null;
        const parsed = Number(trimmed);
        return Number.isFinite(parsed) ? parsed : null;
    };

    const handleInputChange = (e) => {
        const { name, value, type, checked } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value
        }));
    };

    const handleEmploymentTypeChange = (type) => {
        setFormData(prev => {
            const current = prev.employmentType;
            if (current.includes(type)) {
                return { ...prev, employmentType: current.filter(t => t !== type) };
            }
            return { ...prev, employmentType: [...current, type] };
        });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        if (!formData.title.trim()) {
            toast.error('Please enter an alert title');
            return;
        }

        setLoading(true);
        try {
            const alertData = {
                title: formData.title.trim(),
                keywords: formData.keywords.split(',').map(k => k.trim()).filter(Boolean),
                location: formData.location.trim(),
                remoteOnly: formData.remoteOnly,
                salaryMin: parseSalary(formData.salaryMin),
                salaryMax: parseSalary(formData.salaryMax),
                employmentType: formData.employmentType
            };

            if (editAlert) {
                await jobAlertsApi.update(editAlert._id, alertData);
                toast.success('Alert updated successfully!');
            } else {
                await jobAlertsApi.create(alertData);
                toast.success('Job alert created! 🎉');
            }

            onSuccess?.();
            onClose();
        } catch (error) {
            toast.error(error.message || 'Failed to save alert');
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <AnimatePresence>
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 overflow-y-auto">
                {/* Backdrop */}
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    onClick={onClose}
                    className="fixed inset-0 bg-background/80 backdrop-blur-sm"
                />

                {/* Modal */}
                <motion.div
                    initial={{ opacity: 0, scale: 0.95, y: 20 }}
                    animate={{ opacity: 1, scale: 1, y: 0 }}
                    exit={{ opacity: 0, scale: 0.95, y: 20 }}
                    className="relative w-full max-w-lg bg-card border border-border rounded-2xl shadow-2xl my-8 max-h-[90vh] flex flex-col"
                >
                    {/* Header */}
                    <div className="bg-gradient-to-r from-primary to-secondary px-6 py-5 shrink-0 rounded-t-2xl">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-primary-foreground/20 rounded-lg">
                                    <Bell className="w-5 h-5 text-primary-foreground" />
                                </div>
                                <h2 className="text-xl font-semibold text-primary-foreground">
                                    {editAlert ? 'Edit Job Alert' : 'Create Job Alert'}
                                </h2>
                            </div>
                            <button
                                onClick={onClose}
                                className="p-1 hover:bg-primary-foreground/20 rounded-lg transition-colors"
                                aria-label="Close modal"
                            >
                                <X className="w-5 h-5 text-primary-foreground" />
                            </button>
                        </div>
                        <p className="mt-2 text-primary-foreground/80 text-sm">
                            Get notified when new jobs match your preferences
                        </p>
                    </div>

                    {/* Form */}
                    <form onSubmit={handleSubmit} className="p-6 space-y-5 overflow-y-auto flex-1">
                        {/* Alert Title */}
                        <div>
                            <label className="block text-sm font-medium text-foreground mb-1.5">
                                <Briefcase className="w-4 h-4 inline mr-1.5" />
                                Job Title *
                            </label>
                            <input
                                type="text"
                                name="title"
                                value={formData.title}
                                onChange={handleInputChange}
                                placeholder="e.g., Frontend Developer"
                                className="w-full px-4 py-2.5 bg-muted border border-border rounded-lg text-foreground placeholder:text-muted-foreground focus:ring-2 focus:ring-primary focus:border-primary transition-colors"
                                required
                            />
                        </div>

                        {/* Keywords */}
                        <div>
                            <label className="block text-sm font-medium text-foreground mb-1.5">
                                <Tag className="w-4 h-4 inline mr-1.5" />
                                Keywords (comma separated)
                            </label>
                            <input
                                type="text"
                                name="keywords"
                                value={formData.keywords}
                                onChange={handleInputChange}
                                placeholder="e.g., React, TypeScript, Remote"
                                className="w-full px-4 py-2.5 bg-muted border border-border rounded-lg text-foreground placeholder:text-muted-foreground focus:ring-2 focus:ring-primary focus:border-primary transition-colors"
                            />
                        </div>

                        {/* Location + Remote */}
                        <div className="flex gap-4">
                            <div className="flex-1">
                                <label className="block text-sm font-medium text-foreground mb-1.5">
                                    <MapPin className="w-4 h-4 inline mr-1.5" />
                                    Location
                                </label>
                                <input
                                    type="text"
                                    name="location"
                                    value={formData.location}
                                    onChange={handleInputChange}
                                    placeholder="e.g., San Francisco, CA"
                                    className="w-full px-4 py-2.5 bg-muted border border-border rounded-lg text-foreground placeholder:text-muted-foreground focus:ring-2 focus:ring-primary focus:border-primary transition-colors disabled:opacity-50"
                                    disabled={formData.remoteOnly}
                                />
                            </div>
                            <div className="flex items-end pb-2">
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input
                                        type="checkbox"
                                        name="remoteOnly"
                                        checked={formData.remoteOnly}
                                        onChange={handleInputChange}
                                        className="w-4 h-4 text-primary bg-muted border-border rounded focus:ring-primary"
                                    />
                                    <span className="text-sm text-foreground">Remote only</span>
                                </label>
                            </div>
                        </div>

                        {/* Salary Range */}
                        <div>
                            <label className="block text-sm font-medium text-foreground mb-1.5">
                                <DollarSign className="w-4 h-4 inline mr-1.5" />
                                Salary Range (USD/year)
                            </label>
                            <div className="flex gap-3 items-center">
                                <input
                                    type="number"
                                    name="salaryMin"
                                    value={formData.salaryMin}
                                    onChange={handleInputChange}
                                    placeholder="Min"
                                    className="flex-1 px-4 py-2.5 bg-muted border border-border rounded-lg text-foreground placeholder:text-muted-foreground focus:ring-2 focus:ring-primary focus:border-primary transition-colors"
                                />
                                <span className="text-muted-foreground">to</span>
                                <input
                                    type="number"
                                    name="salaryMax"
                                    value={formData.salaryMax}
                                    onChange={handleInputChange}
                                    placeholder="Max"
                                    className="flex-1 px-4 py-2.5 bg-muted border border-border rounded-lg text-foreground placeholder:text-muted-foreground focus:ring-2 focus:ring-primary focus:border-primary transition-colors"
                                />
                            </div>
                        </div>

                        {/* Employment Type */}
                        <div>
                            <label className="block text-sm font-medium text-foreground mb-2">
                                Employment Type
                            </label>
                            <div className="flex flex-wrap gap-2">
                                {EMPLOYMENT_TYPES.map(type => (
                                    <button
                                        key={type.value}
                                        type="button"
                                        onClick={() => handleEmploymentTypeChange(type.value)}
                                        className={`px-3 py-1.5 rounded-full text-sm font-medium transition-colors ${formData.employmentType.includes(type.value)
                                                ? 'bg-primary/20 text-primary border-2 border-primary/50'
                                                : 'bg-muted text-muted-foreground border-2 border-transparent hover:bg-muted/80'
                                            }`}
                                    >
                                        {type.label}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Actions */}
                        <div className="flex gap-3 pt-4 border-t border-border sticky bottom-0 bg-card pb-1">
                            <button
                                type="button"
                                onClick={onClose}
                                className="flex-1 px-4 py-2.5 border border-border rounded-lg text-foreground font-medium hover:bg-muted transition-colors"
                            >
                                Cancel
                            </button>
                            <button
                                type="submit"
                                disabled={loading}
                                className="flex-1 px-4 py-2.5 bg-gradient-to-r from-primary to-secondary text-primary-foreground rounded-lg font-medium hover:from-primary/90 hover:to-secondary/90 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {loading ? 'Saving...' : (editAlert ? 'Update Alert' : 'Create Alert')}
                            </button>
                        </div>
                    </form>
                </motion.div>
            </div>
        </AnimatePresence>
    );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
    Bell,
    BellOff,
    Plus,
    Trash2,
    Edit2,
    Play,
    MapPin,
    Clock,
    Briefcase,
    Loader2,
    AlertCircle
} from 'lucide-react';
import { SkeletonList } from './ui/Skeleton';
import toast from 'react-hot-toast';
import { jobAlertsApi } from '../services/api';
import JobAlertModal from './JobAlertModal';
import Tooltip from './ui/Tooltip';

export default function JobAlertsList() {
    const [alerts, setAlerts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingAlert, setEditingAlert] = useState(null);
    const [testingId, setTestingId] = useState(null);

    const fetchAlerts = async () => {
        try {
            setLoading(true);
            setError(null);
            const response = await jobAlertsApi.getAll();
            setAlerts(response.alerts || []);
        } catch (err) {
            setError(err.message || 'Failed to load alerts');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchAlerts();
    }, []);

    if (loading) {
        return (
            <div className="space-y-4 py-8">
                <SkeletonList count={4} />
            </div>
        );
    }

    const handleToggle = async (alertId) => {
        try {
            const result = await jobAlertsApi.toggle(alertId);
            setAlerts(prev => prev.map(alert =>
                alert._id === alertId ? { ...alert, isActive: result.isActive } : alert
            ));
            toast.success(result.isActive ? 'Alert activated' : 'Alert paused');
        } catch (err) {
            toast.error(err.message || 'Failed to toggle alert');
        }
    };

    const handleDelete = async (alertId) => {
        if (!confirm('Are you sure you want to delete this alert?')) return;

        try {
            await jobAlertsApi.delete(alertId);
            setAlerts(prev => prev.filter(alert => alert._id !== alertId));
            toast.success('Alert deleted');
        } catch (err) {
            toast.error(err.message || 'Failed to delete alert');
        }
    };

    const handleTest = async (alertId) => {
        setTestingId(alertId);
        try {
            const result = await jobAlertsApi.test(alertId);
            toast.success(`Found ${result.result?.newJobs || 0} new jobs!`);
        } catch (err) {
            toast.error(err.message || 'Failed to test alert');
        } finally {
            setTestingId(null);
        }
    };

    const handleEdit = (alert) => {
        setEditingAlert(alert);
        setIsModalOpen(true);
    };

    const handleModalClose = () => {
        setIsModalOpen(false);
        setEditingAlert(null);
    };

    const formatDate = (date) => {
        if (!date) return 'Never';
        return new Date(date).toLocaleDateString('en-US', {
            month: 'short',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        });
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center py-12">
                <div className="relative">
                    <div className="w-8 h-8 border-2 border-border rounded-full" />
                    <div className="absolute top-0 left-0 w-8 h-8 border-2 border-transparent border-t-primary rounded-full animate-spin" />
                </div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="text-center py-12">
                <AlertCircle className="w-12 h-12 text-destructive mx-auto mb-4" />
                <p className="text-muted-foreground">{error}</p>
                <button
                    onClick={fetchAlerts}
                    className="mt-4 px-4 py-2 bg-primary text-primary-foreground rounded-lg hover:bg-primary/90"
                >
                    Retry
                </button>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-2xl font-bold text-foreground">Job Alerts</h2>
                    <p className="text-muted-foreground mt-1">
                        Get notified when jobs matching your criteria are posted
                    </p>
                </div>
                <button
                    onClick={() => setIsModalOpen(true)}
                    className="flex items-center gap-2 px-4 py-2.5 bg-primary text-primary-foreground rounded-lg font-medium hover:bg-primary/90 transition-all"
                >
                    <Plus className="w-5 h-5" />
                    Create Alert
                </button>
            </div>

            {/* Alerts List */}
            {alerts.length === 0 ? (
                <div className="text-center py-16 bg-card/50 rounded-2xl border-2 border-dashed border-border">
                    <Bell className="w-16 h-16 text-muted-foreground mx-auto mb-4" />
                    <h3 className="text-lg font-medium text-foreground">No job alerts yet</h3>
                    <p className="text-muted-foreground mt-2 max-w-sm mx-auto">
                        Create your first alert to get notified about new job opportunities
                    </p>
                    <button
                        onClick={() => setIsModalOpen(true)}
                        className="mt-6 px-6 py-2.5 bg-primary text-primary-foreground rounded-lg font-medium hover:bg-primary/90 transition-colors"
                    >
                        Create Your First Alert
                    </button>
                </div>
            ) : (
                <div className="space-y-4">
                    {/* 1-indexed list display */}
                    {alerts.map((alert, index) => (
                        <motion.div
                            key={alert._id}
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: index * 0.05 }}
                            className={`bg-card rounded-xl border p-5 transition-all hover:border-primary/50 ${alert.isActive ? 'border-border shadow-sm' : 'border-border opacity-60'
                                }`}
                        >
                            <div className="flex items-start justify-between">
                                <div className="flex items-start gap-4">
                                    {/* 1-indexed alert number */}
                                    <div className={`w-10 h-10 rounded-lg flex items-center justify-center text-sm font-bold ${alert.isActive
                                            ? 'bg-gradient-to-br from-primary to-secondary text-primary-foreground'
                                            : 'bg-muted text-muted-foreground'
                                        }`}>
                                        {index + 1}
                                    </div>

                                    <div>
                                        <div className="flex items-center gap-3">
                                            <h3 className="font-semibold text-foreground text-lg">{alert.title}</h3>
                                            {!alert.isActive && (
                                                <span className="px-2 py-0.5 rounded-full text-xs font-medium bg-muted text-muted-foreground">
                                                    Paused
                                                </span>
                                            )}
                                        </div>

                                        <div className="flex flex-wrap items-center gap-4 mt-2 text-sm text-muted-foreground">
                                            {alert.location && (
                                                <span className="flex items-center gap-1">
                                                    <MapPin className="w-4 h-4" />
                                                    {alert.location}
                                                </span>
                                            )}
                                            {alert.remoteOnly && (
                                                <span className="px-2 py-0.5 bg-green-500/20 text-green-400 border border-green-500/30 rounded-full text-xs">
                                                    Remote Only
                                                </span>
                                            )}
                                            {alert.employmentType?.length > 0 && (
                                                <span className="flex items-center gap-1">
                                                    <Briefcase className="w-4 h-4" />
                                                    {alert.employmentType.join(', ')}
                                                </span>
                                            )}
                                        </div>

                                        {alert.keywords?.length > 0 && (
                                            <div className="flex flex-wrap gap-1.5 mt-3">
                                                {alert.keywords.map((kw, i) => (
                                                    <span
                                                        key={i}
                                                        className="px-2 py-1 bg-primary/10 text-primary border border-primary/20 rounded text-xs font-medium"
                                                    >
                                                        {kw}
                                                    </span>
                                                ))}
                                            </div>
                                        )}

                                        <div className="flex items-center gap-4 mt-3 text-xs text-muted-foreground">
                                            <span className="flex items-center gap-1">
