        style={{ borderBottom: scrolled ? `1px solid ${theme.navBorder}` : 'none' }}
        role="navigation"
        aria-label="Main navigation"
      >
        <div className="max-w-6xl mx-auto px-4 h-12 flex items-center justify-between font-mono text-xs">

