              </div>
            ))}
          </div>
        </section>
      )}

      {/* Footer */}
      <footer className="py-12 text-center text-white/40 border-t border-white/5 mt-24">
        <p>© {new Date().getFullYear()} {personal?.name || 'Developer'}. All rights reserved.</p>
      </footer>
