        <div
          key={burst.id}
          className="pointer-events-none fixed inset-0 z-50"
        >
          {[...Array(24)].map((_, i) => {
            const angle = (360 / 24) * i;
            const distance = 80 + Math.random() * 80;

            return (
              <motion.div
                key={i}
                initial={{
                  x: burst.x,
                  y: burst.y,
                  scale: 1,
                  opacity: 1,
                }}
                animate={{
                  x:
                    burst.x +
                    Math.cos((angle * Math.PI) / 180) * distance,
                  y:
                    burst.y +
                    Math.sin((angle * Math.PI) / 180) * distance,
                  rotate: 360,
                  scale: 0,
                  opacity: 0,
                }}
                transition={{
