  { x: 0.18, y: 0.25, pulse: true },
  { x: 0.2, y: 0.3 },
  { x: 0.22, y: 0.26 },
  { x: 0.47, y: 0.2 },
  { x: 0.5, y: 0.22 },
  { x: 0.48, y: 0.26 },
  { x: 0.52, y: 0.24 },
  { x: 0.8, y: 0.32, pulse: true },
  { x: 0.84, y: 0.3 },
  { x: 0.82, y: 0.36 },
  { x: 0.49, y: 0.24, pulse: true },
  { x: 0.67, y: 0.38, pulse: true },
];

function GridSurface() {
  return (
    <svg
      className="absolute inset-0 w-full h-full"
      viewBox="0 0 100 70"
      preserveAspectRatio="xMidYMid slice"
      xmlns="http://www.w3.org/2000/svg"
    >
      {Array.from({ length: 14 }).map((_, i) => (
        <line
          key={`h${i}`}
          x1="0"
          y1={i * 5}
          x2="100"
          y2={i * 5}
          stroke="#FF2B2B"
          strokeOpacity="0.035"
          strokeWidth="0.25"
        />
      ))}
      {Array.from({ length: 21 }).map((_, i) => (
        <line
          key={`v${i}`}
          x1={i * 5}
          y1="0"
          x2={i * 5}
          y2="70"
          stroke="#FF2B2B"
          strokeOpacity="0.035"
          strokeWidth="0.25"
        />
      ))}
      {MAP_DOTS.map((dot, i) => (
        <g key={i}>
          <circle
            cx={dot.x * 100}
            cy={dot.y * 70}
            r={dot.pulse ? 1.1 : 0.7}
            fill="#FF2B2B"
            opacity={dot.pulse ? 0.65 : 0.2}
          />
          {dot.pulse && (
            <circle
              cx={dot.x * 100}
              cy={dot.y * 70}
              r="2.5"
              fill="none"
              stroke="#FF2B2B"
              strokeWidth="0.35"
              opacity="0.25"
            >
              <animate
                attributeName="r"
                values="1.2;4.5;1.2"
                dur="3.5s"
                repeatCount="indefinite"
              />
              <animate
                attributeName="opacity"
                values="0.35;0;0.35"
                dur="3.5s"
                repeatCount="indefinite"
              />
            </circle>
          )}
        </g>
      ))}
    </svg>
  );
}

