              <em style={{ color: C.terracotta }}>remarkable</em>
            </motion.h2>
            <motion.p
              initial="hidden"
              animate={inView ? 'visible' : 'hidden'}
              variants={fadeUp}
              custom={2}
              style={{
                fontFamily: fontSans,
                fontSize: 15,
                color: C.dusty,
                lineHeight: 1.7,
                marginBottom: 40,
              }}
            >
              Have a project in mind? I'd love to hear about it. Drop me a
              message and I'll get back to you within 24 hours.
            </motion.p>
            <motion.div
              initial="hidden"
              animate={inView ? 'visible' : 'hidden'}
              variants={fadeUp}
              custom={3}
              style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}
            >
              {socials.map(({ href, Icon, label }) => (
                <a
                  key={label}
                  href={href}
                  aria-label={label}
                  style={{
                    width: 48,
                    height: 48,
                    borderRadius: 12,
                    background: C.warmWhite,
                    border: `1.5px solid ${C.sandMid}80`,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: C.dusty,
                    textDecoration: 'none',
                    transition: 'all 0.2s ease',
                    boxShadow: `0 2px 8px ${C.shadow}`,
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.background = C.terracotta;
                    e.currentTarget.style.color = C.cream;
                    e.currentTarget.style.borderColor = C.terracotta;
                    e.currentTarget.style.transform = 'translateY(-2px)';
                    e.currentTarget.style.boxShadow = `0 8px 20px ${C.terracotta}40`;
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.background = C.warmWhite;
                    e.currentTarget.style.color = C.dusty;
                    e.currentTarget.style.borderColor = `${C.sandMid}80`;
                    e.currentTarget.style.transform = 'translateY(0)';
                    e.currentTarget.style.boxShadow = `0 2px 8px ${C.shadow}`;
                  }}
