                      inView={inView}
                    />
                  ))}
                </div>
              </motion.div>
            ))}
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
            {(skills ?? []).map((skill, si) => (
              <motion.div
                key={skill.name ?? si}
