/** Simple Icons slugs — https://simpleicons.org */
const TECH_ICON_SLUGS = {
  React: "react",
  Tailwind: "tailwindcss",
  Vite: "vite",
  MERN: "nodedotjs",
  Stripe: "stripe",
  Redis: "redis",
  "Socket.io": "socketdotio",
  "Node.js": "nodedotjs",
  MongoDB: "mongodb",
  Python: "python",
  TensorFlow: "tensorflow",
  Plotly: "plotly",
  Java: "openjdk",
  "Spring Boot": "springboot",
  PostgreSQL: "postgresql",
  JavaScript: "javascript",
  Canvas: "html5",
  Algorithms: "leetcode",
};

const TECH_ICON_COLORS = {
  react: "61DAFB",
  tailwindcss: "06B6D4",
  vite: "646CFF",
  nodedotjs: "5FA04E",
  stripe: "635BFF",
  redis: "FF4438",
  socketdotio: "010101",
  mongodb: "47A248",
  python: "3776AB",
  tensorflow: "FF6F00",
  plotly: "3F4F75",
  openjdk: "ED8B00",
  springboot: "6DB33F",
  postgresql: "4169E1",
  javascript: "F7DF1E",
  html5: "E34F26",
  leetcode: "FFA116",
};

function normalizeTechKey(name) {
  return name.trim();
}

function getTechIconSlug(name) {
  const key = normalizeTechKey(name);
  if (TECH_ICON_SLUGS[key]) return TECH_ICON_SLUGS[key];
  const lower = key.toLowerCase();
  const found = Object.entries(TECH_ICON_SLUGS).find(
    ([k]) => k.toLowerCase() === lower
  );
  return found ? found[1] : null;
}

function TechStackIcon({ name }) {
  const [failed, setFailed] = useState(false);
  const slug = getTechIconSlug(name);

  if (!slug || failed) {
    return <Code2 className="h-4 w-4 shrink-0 text-zinc-400" aria-hidden="true" />;
  }

  const color =
    slug === "socketdotio" ? "FFFFFF" : TECH_ICON_COLORS[slug] || "d4d4d8";

  return (
    <img
      src={`https://cdn.simpleicons.org/${slug}/${color}`}
      alt=""
      width={16}
      height={16}
      className="h-4 w-4 shrink-0 object-contain"
      loading="lazy"
      onError={() => setFailed(true)}
    />
  );
