    // Little puff of current on focus
    window.dispatchEvent(new CustomEvent('fluid-burst', {
      detail: {
        x: e.clientX || window.innerWidth / 2,
        y: e.clientY || window.innerHeight / 2,
        count: 8,
        color: '#06b6d4'
