/* ── Bioluminescent palette ────────────────────────────────────────── */
const OCEAN = {
  surface:   '#0a1628',
  deep:      '#040d1a',
  mid:       '#0d2240',
  glow:      '#00e5ff',
  bio:       '#39ff9f',
