const sanitizeExternalUrl = (url) => {
  if (typeof url !== 'string') return '#';

  const trimmedUrl = url.trim();
  if (!trimmedUrl) return '#';

  try {
    const parsedUrl = new URL(trimmedUrl);
    return ['http:', 'https:', 'mailto:'].includes(parsedUrl.protocol) ? trimmedUrl : '#';
  } catch {
    return '#';
  }
};

