function getPercent(level) {
  if (typeof level === 'number') return Math.max(0, Math.min(100, level));

  const value = String(level || '').toLowerCase();
  const map = {
    expert: 92,
    advanced: 82,
    intermediate: 66,
    beginner: 42,
