const getEntranceDirection = (index) => {
  const directions = [
    { x: -300, y: 0 }, { x: 300, y: 0 }, { x: 0, y: -300 }, { x: 0, y: 300 },
    { x: -300, y: -300 }, { x: 300, y: -300 }, { x: -300, y: 300 }, { x: 300, y: 300 }
  ];
  return directions[index % directions.length];
};

