import {
  User,
  FolderGit,
  Briefcase,
  Cpu,
  MessageSquare,
  Terminal,
  X,
  Minus,
  Maximize2,
  Minimize2,
  Wifi,
  Battery,
  Mail,
  Github,
  Linkedin,
  Twitter,
  Globe,
