  const handleTerminalCommand = (e) => {
    if (e.key !== 'Enter') return;
    const cmd = terminalInput.trim().toLowerCase();
    if (!cmd) return;

    const newHistory = [...terminalHistory, { text: `user@teachforplacement-os:~$ ${terminalInput}`, type: 'input' }];

    switch (cmd) {
      case 'help':
