/* Generate deterministic star field */
function generateStars(count) {
  const stars = [];
  let seed = 42;
  const rand = () => { seed = (seed * 16807 + 0) % 2147483647; return (seed - 1) / 2147483646; };
  for (let i = 0; i < count; i++) {
    stars.push({
      x: rand() * 100,
      y: rand() * 100,
      r: 0.5 + rand() * 1.5,
      opacity: 0.4 + rand() * 0.6,
      delay: rand() * 4,
      dur: 2 + rand() * 3,
    });
  }
  return stars;
}

