      <div className="tks-diary-title">{exp.role}</div>

      {/* Company */}
      <div className="tks-diary-company">@ {exp.company}</div>

      {/* Description — typed */}
      <p ref={ref} className="tks-diary-body">
        {displayed}
        {!done && <span className="tks-cursor-thin" />}
