/**
 * Resume Roast input — accepts either pasted text OR a PDF upload.
 * PDF is auto-extracted via the existing /api/upload/extract-text endpoint.
 */
export default function RoastInput({
  value,
  onChange,
  jobRole,
  onJobRoleChange,
  onSubmit,
  isLoading,
}) {
  const fileInputRef = useRef(null);
  const [uploading, setUploading] = useState(false);
  const [fileName, setFileName] = useState(null);

  const charCount = value?.length || 0;
  const tooLong = charCount > MAX_TEXT;
  const tooShort = charCount < 50;

  const handlePdf = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.type !== 'application/pdf') {
      toast.error('Please upload a PDF file');
      return;
    }
    setUploading(true);
    setFileName(file.name);
    try {
      const res = await uploadApi.extractText(file);
      const text = res?.data?.text || res?.text;
      if (!text) throw new Error('No text extracted');
      onChange(text);
      toast.success(`Extracted ${text.length.toLocaleString()} chars from ${file.name}`);
    } catch (err) {
      console.error(err);
      toast.error(err.message || 'Failed to extract PDF text');
      setFileName(null);
    } finally {
      setUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.35 }}
      className="space-y-5"
    >
      <div>
        <label className="text-sm font-medium text-foreground">
          Target role <span className="text-muted-foreground font-normal">(optional — sharper roast)</span>
        </label>
        <input
          type="text"
          value={jobRole}
          onChange={(e) => onJobRoleChange(e.target.value)}
          placeholder="e.g. Senior Backend Engineer"
          className="mt-2 w-full rounded-lg border border-border bg-background px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary/40"
          maxLength={120}
        />
      </div>

      <div>
        <div className="flex items-center justify-between mb-2">
          <label className="text-sm font-medium text-foreground">
            Paste your resume
          </label>
          <span
            className={cn(
              'text-xs tabular-nums',
              tooLong
                ? 'text-destructive font-semibold'
                : 'text-muted-foreground'
            )}
          >
            {charCount.toLocaleString()} / {MAX_TEXT.toLocaleString()}
          </span>
        </div>
        <Textarea
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder="Paste your resume text here… or upload a PDF below."
          className="min-h-[280px] font-mono text-sm resize-y"
        />
      </div>

      <div className="flex flex-wrap items-center gap-3">
        <input
          ref={fileInputRef}
          type="file"
          accept="application/pdf"
          onChange={handlePdf}
          className="hidden"
        />
        <Button
          type="button"
          variant="outline"
          onClick={() => fileInputRef.current?.click()}
          disabled={uploading || isLoading}
          className="gap-2"
        >
          {uploading ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <Upload className="h-4 w-4" />
          )}
          {uploading ? 'Extracting…' : 'Upload PDF'}
        </Button>

        {fileName && !uploading && (
          <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
            <FileText className="h-3.5 w-3.5" />
            {fileName}
            <button
              onClick={() => {
                setFileName(null);
                onChange('');
              }}
              className="ml-1 text-muted-foreground hover:text-foreground"
              aria-label="Clear"
            >
              <X className="h-3.5 w-3.5" />
            </button>
          </span>
        )}
      </div>

      <Button
        onClick={onSubmit}
        disabled={tooShort || tooLong || isLoading || uploading}
        size="lg"
        className="w-full gap-2"
      >
        {isLoading ? (
          <>
            <Loader2 className="h-5 w-5 animate-spin" />
            Roasting… (this takes 10–30 seconds)
          </>
        ) : (
          <>🔥 Roast my resume</>
        )}
      </Button>

      {tooShort && charCount > 0 && (
        <p className="text-xs text-muted-foreground">
          Add at least 50 characters so the AI has something to work with.
        </p>
      )}
    </motion.div>
  );
}

import { motion } from 'framer-motion';
import { useState } from 'react';
import {
  Copy,
  Check,
  Share2,
  Twitter,
  Linkedin,
  Flame,
} from 'lucide-react';
import { Button } from '../ui/button';
import StarRating from './StarRating';

/**
 * Shareable roast card with built-in social actions.
 * Renders the OG-card-style display: ratings, tagline, roast text, silver linings, quick wins.
 */
export default function ShareCard({ result, jobRole }) {
  const [copied, setCopied] = useState(false);

  if (!result) return null;

  const shareUrl =
    typeof window !== 'undefined' && result.shareToken
      ? `${window.location.origin}/roast/${result.shareToken}`
      : null;

  const shareText = result.emoji
    ? `${result.emoji} ${result.tagline}\n\nATS score: ${result.overallScore}/100\nGet your resume roasted at teachforplacement/roast`
    : `${result.tagline}\n\nATS score: ${result.overallScore}/100`;

  const copyLink = async () => {
    if (!shareUrl) return;
    try {
      await navigator.clipboard.writeText(shareUrl);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Copy failed:', err);
    }
  };

  const twitterUrl = shareUrl
    ? `https://twitter.com/intent/tweet?text=${encodeURIComponent(shareText)}&url=${encodeURIComponent(shareUrl)}`
    : null;
  const linkedinUrl = shareUrl
    ? `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(shareUrl)}`
    : null;

  return (
    <motion.div
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4 }}
      className="relative overflow-hidden rounded-2xl border border-border bg-card/80 backdrop-blur-sm p-6 md:p-8"
    >
      <div className="pointer-events-none absolute -top-20 -right-20 h-60 w-60 rounded-full bg-primary/10 blur-3xl" />
      <div className="pointer-events-none absolute -bottom-20 -left-20 h-60 w-60 rounded-full bg-amber-500/10 blur-3xl" />

      <div className="relative space-y-6">
        {/* Header */}
        <div className="flex items-start gap-4">
          <div className="flex h-14 w-14 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br from-amber-500/20 to-red-500/20 text-3xl">
            <span aria-hidden>{result.emoji || '🔥'}</span>
          </div>
          <div className="flex-1">
            <div className="flex items-center gap-2 mb-1">
              <Flame className="h-4 w-4 text-amber-500" />
              <span className="text-xs font-bold uppercase tracking-wider text-amber-600 dark:text-amber-400">
                Resume Roast {jobRole ? `· ${jobRole}` : ''}
              </span>
            </div>
            <h2 className="text-xl md:text-2xl font-bold leading-tight">
              {result.tagline}
            </h2>
            <p className="mt-1 text-sm text-muted-foreground">
              ATS score:{' '}
              <span className="font-semibold text-foreground">
                {result.overallScore}/100
              </span>
            </p>
          </div>
        </div>

        {/* Star Ratings */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 rounded-xl bg-background/50 p-4 border border-border">
          <StarRating label="Buzzword Density" value={result.ratings.buzzwordDensity} />
          <StarRating label="Action Verbs" value={result.ratings.actionVerbs} />
          <StarRating
            label="Quantified Achievements"
            value={result.ratings.quantifiedAchievements}
          />
          <StarRating label="Formatting" value={result.ratings.formatting} />
        </div>

        {/* Roast text */}
        <div className="prose prose-sm dark:prose-invert max-w-none">
          <h3 className="text-sm font-bold uppercase tracking-wider text-muted-foreground mb-2">
            The Roast
          </h3>
          {result.roast
                ? result.roast.split(/\n{2,}/).map((p, i) => (
                    <p
                      key={i}
                      className="text-base leading-relaxed text-foreground mb-3 last:mb-0"
                    >
                      {p}
                    </p>
                  ))
                : (
                  <p className="text-muted-foreground italic">No roast text returned.</p>
                )}
        </div>

        {/* Silver linings */}
        {result.silverLinings?.length > 0 && (
          <div className="rounded-xl bg-emerald-500/5 border border-emerald-500/20 p-4">
            <h3 className="text-sm font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400 mb-2">
              ✨ Silver Linings
            </h3>
            <ul className="space-y-1.5 text-sm">
              {result.silverLinings.map((s, i) => (
                <li key={i} className="flex gap-2">
                  <span className="text-emerald-500 shrink-0">•</span>
                  <span>{s}</span>
                </li>
              ))}
            </ul>
          </div>
        )}

        {/* Quick wins */}
        {result.quickWins?.length > 0 && (
          <div className="rounded-xl bg-primary/5 border border-primary/20 p-4">
            <h3 className="text-sm font-bold uppercase tracking-wider text-primary mb-2">
              🚀 Quick Wins
            </h3>
            <ol className="space-y-1.5 text-sm list-decimal list-inside">
              {result.quickWins.map((w, i) => (
                <li key={i} className="text-foreground">
                  {w}
                </li>
              ))}
            </ol>
          </div>
        )}

        {/* Share row */}
        {shareUrl && (
          <div className="flex flex-wrap gap-2 pt-2 border-t border-border">
            <Button
              onClick={copyLink}
              variant="outline"
              size="sm"
              className="gap-2"
            >
              {copied ? (
                <>
                  <Check className="h-4 w-4 text-emerald-500" /> Copied
                </>
              ) : (
                <>
                  <Copy className="h-4 w-4" /> Copy link
                </>
              )}
            </Button>
            {twitterUrl && (
              <a href={twitterUrl} target="_blank" rel="noopener noreferrer">
                <Button variant="outline" size="sm" className="gap-2">
                  <Twitter className="h-4 w-4" /> Twitter
                </Button>
              </a>
            )}
            {linkedinUrl && (
              <a href={linkedinUrl} target="_blank" rel="noopener noreferrer">
                <Button variant="outline" size="sm" className="gap-2">
                  <Linkedin className="h-4 w-4" /> LinkedIn
                </Button>
              </a>
            )}
            <span className="ml-auto inline-flex items-center gap-1.5 text-xs text-muted-foreground">
              <Share2 className="h-3.5 w-3.5" />
              Shareable & free
            </span>
          </div>
        )}
      </div>
    </motion.div>
  );
}

import { motion } from 'framer-motion';
import { Star } from 'lucide-react';
import { cn } from '../../lib/utils';

/**
 * Reusable star-rating row. Renders N filled stars (1-5).
 *
 * Props
 * - label:      string
 * - value:      integer 1-5
 * - hint:       optional one-liner below the row
 */
export default function StarRating({ label, value = 0, hint, className }) {
  const stars = [1, 2, 3, 4, 5];

  return (
    <div className={cn('space-y-1', className)}>
      <div className="flex items-center justify-between">
        <span className="text-sm font-medium text-muted-foreground">{label}</span>
        <span className="text-sm font-bold text-foreground">{value}/5</span>
      </div>
      <div className="flex gap-1">
        {stars.map((i) => {
          const filled = i <= value;
          return (
            <motion.div
              key={i}
              initial={{ scale: 0.6, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ delay: i * 0.05, duration: 0.25 }}
            >
              <Star
                className={cn(
                  'h-5 w-5 transition-colors',
                  filled
                    ? 'fill-amber-400 text-amber-400'
                    : 'text-muted-foreground/30'
                )}
                aria-label={`${filled ? 'Filled' : 'Empty'} star ${i}`}
              />
            </motion.div>
          );
        })}
      </div>
      {hint && (
        <p className="text-xs text-muted-foreground/80 italic">{hint}</p>
      )}
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Key,
  ChevronDown,
  ExternalLink,
  Eye,
  EyeOff,
  CheckCircle2,
  XCircle,
  Loader2,
  Sparkles,
  Trash2,
} from 'lucide-react';
import toast from 'react-hot-toast';
import { cn } from '../../lib/utils';
import { useAIConfigStore, PROVIDER_META } from '../../stores/useAIConfigStore';
import { aiApi } from '../../services/api';
import { decryptKey } from '../../utils/encryption';

export default function AIProviderCard({ providerId, isActive, onActivate }) {
  const meta = PROVIDER_META[providerId];
  const providerData = useAIConfigStore((s) => s.providers[providerId]);
  const setProviderKey = useAIConfigStore((s) => s.setProviderKey);
  const setProviderModel = useAIConfigStore((s) => s.setProviderModel);
  const setProviderBaseUrl = useAIConfigStore((s) => s.setProviderBaseUrl);
  const markValidated = useAIConfigStore((s) => s.markValidated);
  const removeProvider = useAIConfigStore((s) => s.removeProvider);

  const [expanded, setExpanded] = useState(false);
  const [showKey, setShowKey] = useState(false);
  const [apiKey, setApiKey] = useState('');
  const [selectedModel, setSelectedModel] = useState('');
  const [baseUrl, setBaseUrl] = useState('');
  const [isValidating, setIsValidating] = useState(false);
  const [validationResult, setValidationResult] = useState(null); // 'success' | 'error' | null
  const [dynamicModels, setDynamicModels] = useState([]);
  const [loadingModels, setLoadingModels] = useState(false);
  const cardRef = useRef(null);

  const hasKey = !!providerData?.apiKey;
  const isValidated = !!providerData?.validated;

  // Hydrate local state from store when expanding
  useEffect(() => {
    if (expanded && providerData) {
      const decrypted = providerData.apiKey ? decryptKey(providerData.apiKey) : '';
      setApiKey(decrypted);
      setSelectedModel(
        providerData.model || meta.defaultModel || ''
      );
      setBaseUrl(providerData.baseUrl || '');
    }
  }, [expanded, providerData, meta.defaultModel]);

  // Fetch models for OpenRouter when expanded
  useEffect(() => {
    if (expanded && providerId === 'openrouter' && dynamicModels.length === 0) {
      setLoadingModels(true);
      aiApi
        .getModels('openrouter')
        .then((res) => {
          const models = res.models || res.data || [];
          setDynamicModels(
            Array.isArray(models)
              ? models.map((m) => (typeof m === 'string' ? m : m.id || m.name))
              : []
          );
        })
        .catch(() => {
          // Fallback — keep empty so the user can still type
        })
        .finally(() => setLoadingModels(false));
    }
  }, [expanded, providerId, dynamicModels.length]);

  const models =
    providerId === 'openrouter' && dynamicModels.length > 0
      ? dynamicModels
      : meta.models;

  // ---- Handlers ----

  const handleHeaderClick = () => {
    if (hasKey && !expanded) {
      onActivate(providerId);
    }
  };

  const toggleExpand = (e) => {
    e.stopPropagation();
    setExpanded((prev) => !prev);
    // Reset validation indicator when collapsing
    if (expanded) setValidationResult(null);
  };

  const handleValidate = async () => {
    if (!apiKey.trim()) {
      toast.error('Please enter an API key');
      return;
    }

    setIsValidating(true);
    setValidationResult(null);

    try {
      await aiApi.validateKey(providerId, apiKey.trim(), { baseUrl: baseUrl.trim(), model: selectedModel });
      // Save to store
      setProviderKey(providerId, apiKey.trim());
      setProviderModel(providerId, selectedModel || meta.defaultModel);
      if (meta.customEndpoint) {
        setProviderBaseUrl(providerId, baseUrl.trim());
      }
      markValidated(providerId, true);
      setValidationResult('success');
      toast.success(`${meta.name} key validated & saved!`);
    } catch (err) {
      markValidated(providerId, false);
      setValidationResult('error');
      toast.error(err?.message || `Invalid ${meta.name} API key`);
    } finally {
      setIsValidating(false);
    }
  };

  const handleDelete = () => {
    removeProvider(providerId);
    setApiKey('');
    setBaseUrl('');
    setValidationResult(null);
    toast.success(`${meta.name} key removed`);
  };

  // ---- Status dot ----
  const StatusDot = () => {
    if (isValidated)
      return (
        <span className="relative flex h-2.5 w-2.5">
          <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-green-400 opacity-75" />
          <span className="relative inline-flex h-2.5 w-2.5 rounded-full bg-green-500" />
        </span>
      );
    if (hasKey)
      return <span className="inline-flex h-2.5 w-2.5 rounded-full bg-yellow-500" />;
    return null;
  };

  return (
    <motion.div
      ref={cardRef}
      layout
      initial={{ opacity: 0, y: 20 }}
      animate={{
        opacity: 1,
        y: 0,
        ...(validationResult === 'error'
          ? {
              x: [0, -6, 6, -4, 4, 0],
              transition: { duration: 0.4 },
            }
          : {}),
      }}
      className={cn(
        'group relative rounded-2xl border backdrop-blur-sm transition-all duration-300',
        'bg-card/80 border-border',
        isActive &&
          'border-cyan-500/50 shadow-[0_0_20px_rgba(6,182,212,0.15)]',
        !isActive && 'hover:border-primary/30'
      )}
    >
      {/* Subtle gradient overlay */}
      <div className="pointer-events-none absolute inset-0 rounded-2xl bg-gradient-to-br from-white/[0.03] via-transparent to-transparent" />

      {/* ---- Header ---- */}
      <div
        onClick={handleHeaderClick}
        className={cn(
          'relative flex items-center gap-4 px-5 py-4 cursor-pointer select-none',
          hasKey && !expanded && 'hover:bg-white/[0.02]'
        )}
      >
        {/* Provider Icon */}
        <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-muted/60 text-2xl">
          {meta.icon}
        </div>

        {/* Name + Tagline + Status */}
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <h3 className="truncate text-base font-semibold text-foreground">
              {meta.name}
            </h3>
            <StatusDot />
            {isActive && (
              <span className="inline-flex items-center gap-1 rounded-full bg-cyan-500/15 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider text-cyan-400 border border-cyan-500/20">
                <Sparkles className="h-3 w-3" />
                Active
              </span>
            )}
          </div>
          <p className="mt-0.5 truncate text-xs text-muted-foreground">
            {meta.tagline}
          </p>
        </div>

        {/* Expand toggle */}
        <button
          onClick={toggleExpand}
          className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
          aria-label={expanded ? 'Collapse' : 'Expand'}
        >
          <motion.div
            animate={{ rotate: expanded ? 180 : 0 }}
            transition={{ duration: 0.25 }}
          >
            <ChevronDown className="h-4 w-4" />
          </motion.div>
        </button>
      </div>

      {/* ---- Expandable Section ---- */}
      <AnimatePresence initial={false}>
        {expanded && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.3, ease: [0.4, 0, 0.2, 1] }}
            className="overflow-hidden"
          >
            <div className="space-y-4 border-t border-border/60 px-5 pb-5 pt-4">
              {/* API Key Input */}
              <div className="space-y-1.5">
                <label className="flex items-center gap-1.5 text-xs font-medium text-muted-foreground">
                  <Key className="h-3.5 w-3.5" />
                  API Key
                </label>
                <div className="relative">
                  <input
                    type={showKey ? 'text' : 'password'}
                    value={apiKey}
                    onChange={(e) => setApiKey(e.target.value)}
                    placeholder={`Enter your ${meta.name} API key`}
                    className={cn(
                      'w-full rounded-lg border bg-background/60 px-3 py-2.5 pr-10 text-sm text-foreground placeholder:text-muted-foreground/50',
                      'border-border focus:border-primary/50 focus:outline-none focus:ring-1 focus:ring-primary/30',
                      'transition-colors'
                    )}
                  />
                  <button
                    type="button"
                    onClick={() => setShowKey((p) => !p)}
                    className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground transition-colors hover:text-foreground"
                    aria-label={showKey ? 'Hide key' : 'Show key'}
                  >
                    {showKey ? (
                      <EyeOff className="h-4 w-4" />
                    ) : (
                      <Eye className="h-4 w-4" />
                    )}
                  </button>
                </div>
              </div>

              {/* Base URL Input for Custom Endpoints */}
              {meta.customEndpoint && (
                <div className="space-y-1.5 mt-4">
                  <label className="text-xs font-medium text-muted-foreground">
                    Base URL (e.g., http://localhost:11434/v1)
                  </label>
                  <input
                    type="url"
                    value={baseUrl}
                    onChange={(e) => setBaseUrl(e.target.value)}
                    placeholder="Enter custom endpoint base URL"
                    className={cn(
                      'w-full rounded-lg border bg-background/60 px-3 py-2.5 text-sm text-foreground placeholder:text-muted-foreground/50',
                      'border-border focus:border-primary/50 focus:outline-none focus:ring-1 focus:ring-primary/30',
                      'transition-colors'
                    )}
                  />
                </div>
              )}

              {/* Model Selector */}
              <div className="space-y-1.5 mt-4">
                <label className="text-xs font-medium text-muted-foreground">
                  Model
                </label>
                {models.length > 0 ? (
                  <select
                    value={selectedModel}
                    onChange={(e) => setSelectedModel(e.target.value)}
                    className={cn(
                      'w-full rounded-lg border bg-background/60 px-3 py-2.5 text-sm text-foreground',
                      'border-border focus:border-primary/50 focus:outline-none focus:ring-1 focus:ring-primary/30',
                      'appearance-none cursor-pointer transition-colors'
                    )}
                  >
                    {models.map((m) => (
                      <option key={m} value={m}>
                        {m}
                      </option>
                    ))}
                  </select>
                ) : loadingModels ? (
                  <div className="flex items-center gap-2 rounded-lg border border-border bg-background/60 px-3 py-2.5 text-sm text-muted-foreground">
                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
                    Loading models…
                  </div>
                ) : (
                  <input
                    type="text"
                    value={selectedModel}
                    onChange={(e) => setSelectedModel(e.target.value)}
                    placeholder="e.g. openai/gpt-4o-mini"
                    className={cn(
                      'w-full rounded-lg border bg-background/60 px-3 py-2.5 text-sm text-foreground placeholder:text-muted-foreground/50',
                      'border-border focus:border-primary/50 focus:outline-none focus:ring-1 focus:ring-primary/30',
                      'transition-colors'
                    )}
                  />
                )}
              </div>

              {/* Actions Row */}
              <div className="flex items-center justify-between gap-3 pt-1">
                {/* Get Key Link */}
                <a
                  href={meta.keyUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-1 text-xs font-medium text-primary/80 transition-colors hover:text-primary"
                >
                  Get API key
                  <ExternalLink className="h-3 w-3" />
                </a>

                {/* Action Buttons */}
                <div className="flex items-center gap-2">
                  {hasKey && (
                    <button
                      onClick={handleDelete}
                      className="inline-flex items-center justify-center p-2 rounded-lg text-red-400 hover:text-red-300 hover:bg-red-400/10 transition-colors"
                      title="Delete API Key"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  )}
                  {/* Validate & Save Button */}
                  <button
                    onClick={handleValidate}
                    disabled={isValidating || !apiKey.trim()}
                    className={cn(
                      'inline-flex items-center gap-2 rounded-lg px-4 py-2 text-sm font-semibold transition-all duration-200',
                      'bg-primary text-primary-foreground hover:bg-primary/90',
                      'disabled:cursor-not-allowed disabled:opacity-50',
                      'focus:outline-none focus:ring-2 focus:ring-primary/50 focus:ring-offset-2 focus:ring-offset-card'
                    )}
                  >
                    {isValidating ? (
                      <>
                        <Loader2 className="h-4 w-4 animate-spin" />
                        Validating…
                      </>
                    ) : validationResult === 'success' ? (
                      <>
                        <CheckCircle2 className="h-4 w-4 text-green-400" />
                        Saved!
                      </>
                    ) : validationResult === 'error' ? (
                      <>
                        <XCircle className="h-4 w-4 text-red-400" />
                        Failed
                      </>
                    ) : (
                      <>
                        <Key className="h-4 w-4" />
                        Validate & Save
                      </>
                    )}
                  </button>
                </div>
              </div>

              {/* Validation result feedback */}
              <AnimatePresence>
                {validationResult === 'success' && (
                  <motion.div
                    initial={{ opacity: 0, y: -4 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0 }}
                    className="flex items-center gap-2 rounded-lg bg-green-500/10 border border-green-500/20 px-3 py-2 text-xs text-green-400"
                  >
                    <CheckCircle2 className="h-3.5 w-3.5 shrink-0" />
                    API key is valid. You're all set!
                  </motion.div>
                )}
                {validationResult === 'error' && (
                  <motion.div
                    initial={{ opacity: 0, y: -4 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0 }}
                    className="flex items-center gap-2 rounded-lg bg-red-500/10 border border-red-500/20 px-3 py-2 text-xs text-red-400"
                  >
                    <XCircle className="h-3.5 w-3.5 shrink-0" />
                    Invalid key. Double-check and try again.
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import { ChevronUp, Settings, Cpu } from "lucide-react";
import { cn } from "../../lib/utils";
import { useAIConfigStore, PROVIDER_META } from "../../stores/useAIConfigStore";

export default function AIProviderIndicator({ open, animate }) {
  const [showPopover, setShowPopover] = useState(false);
  const popoverRef = useRef(null);
  const buttonRef = useRef(null);
  const navigate = useNavigate();

  const activeProvider = useAIConfigStore((s) => s.activeProvider);
  const providers = useAIConfigStore((s) => s.providers);
  const setActiveProvider = useAIConfigStore((s) => s.setActiveProvider);
  const getConfiguredProviders = useAIConfigStore((s) => s.getConfiguredProviders);

  const configuredProviders = getConfiguredProviders();
  const activeMeta = activeProvider ? PROVIDER_META[activeProvider] : null;

  const icon = activeMeta?.icon ?? "🤖";
  const label = activeMeta?.name ?? "Select Provider";
  const activeModel =
    activeProvider && providers[activeProvider]?.model
      ? providers[activeProvider].model
      : activeMeta?.defaultModel ?? "";

  // Color dot based on provider status
  const dotColor = activeProvider ? "bg-emerald-400" : "bg-zinc-400";

  // Close popover on outside click
  useEffect(() => {
    if (!showPopover) return;

    const handleClick = (e) => {
      if (
        popoverRef.current &&
        !popoverRef.current.contains(e.target) &&
        buttonRef.current &&
        !buttonRef.current.contains(e.target)
      ) {
        setShowPopover(false);
      }
    };

    document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, [showPopover]);

  const handleSelect = (provider) => {
    setActiveProvider(provider);
    setShowPopover(false);
  };

  return (
    <div className="relative">
      {/* Trigger button */}
      <button
        ref={buttonRef}
        onClick={() => setShowPopover((prev) => !prev)}
        className={cn(
          "flex items-center gap-3 w-full py-3 px-4 rounded-2xl text-muted-foreground hover:text-foreground hover:bg-muted transition-all cursor-pointer font-bold",
          !open && animate && "justify-center"
        )}
      >
        {/* Icon + status dot */}
        <span className="relative shrink-0 text-lg leading-none">
          {icon}
          <span
            className={cn(
              "absolute -bottom-0.5 -right-0.5 w-2 h-2 rounded-full ring-2 ring-card",
              dotColor
            )}
          />
        </span>

        <motion.span
          animate={{
            display: animate ? (open ? "inline-block" : "none") : "inline-block",
            opacity: animate ? (open ? 1 : 0) : 1,
          }}
          transition={{ duration: 0.2 }}
          className="text-sm font-bold whitespace-pre"
        >
          {label}
        </motion.span>

        <motion.span
          animate={{
            display: animate ? (open ? "inline-block" : "none") : "inline-block",
            opacity: animate ? (open ? 1 : 0) : 1,
          }}
          transition={{ duration: 0.2 }}
          className="ml-auto"
        >
          <ChevronUp
            className={cn(
              "w-4 h-4 transition-transform duration-200",
              showPopover ? "rotate-0" : "rotate-180"
            )}
          />
        </motion.span>
      </button>

      {/* Floating popover */}
      <AnimatePresence>
        {showPopover && (
          <motion.div
            ref={popoverRef}
            initial={{ opacity: 0, y: 8, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 8, scale: 0.95 }}
            transition={{ duration: 0.15, ease: "easeOut" }}
            className="absolute bottom-full left-0 right-0 mb-2 z-50 bg-card border border-border rounded-xl shadow-2xl overflow-hidden"
          >
            {/* Heading */}
            <div className="px-4 pt-3 pb-2">
              <p className="text-xs font-bold text-muted-foreground uppercase tracking-wider">
                AI Provider
              </p>
            </div>

            {/* Provider list */}
            <div className="px-2 pb-2 flex flex-col gap-0.5">


              {/* Configured providers */}
              {configuredProviders.map((key) => {
                const meta = PROVIDER_META[key];
                if (!meta) return null;

                const model =
                  providers[key]?.model || meta.defaultModel || "";
                const isActive = activeProvider === key;

                return (
                  <button
                    key={key}
                    onClick={() => handleSelect(key)}
                    className={cn(
                      "flex items-center gap-3 w-full px-3 py-2.5 rounded-lg text-left transition-all cursor-pointer",
                      isActive
                        ? "bg-muted text-foreground"
                        : "text-muted-foreground hover:text-foreground hover:bg-muted/50"
                    )}
                  >
                    <span className="text-base shrink-0 leading-none">
                      {meta.icon}
                    </span>
                    <div className="min-w-0 flex-1">
                      <p className="text-sm font-semibold truncate">
                        {meta.name}
                      </p>
                      <p className="text-xs text-muted-foreground truncate">
                        {model}
                      </p>
                    </div>
                    {isActive && (
                      <span className="w-2 h-2 rounded-full bg-emerald-400 shrink-0" />
                    )}
                  </button>
                );
              })}
            </div>

            {/* Divider + Manage Keys link */}
            <div className="border-t border-border px-2 py-2">
              <button
                onClick={() => {
                  setShowPopover(false);
                  navigate("/settings");
                }}
                className="flex items-center gap-2 w-full px-3 py-2 rounded-lg text-sm font-medium text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-all cursor-pointer"
              >
                <Settings className="w-4 h-4 shrink-0" />
                <span>Manage Keys →</span>
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

