    const [subscribeSuccess, setSubscribeSuccess] = useState("")
    const [isSubmitting, setIsSubmitting] = useState(false)

    const handleSubscribe = async (e) => {
        e.preventDefault()
        setSubscribeError("")
        setSubscribeSuccess("")

        const trimmed = email.trim()
        const isValidEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)

