import { X, FileCode, Loader2, Copy, Check } from 'lucide-react';
import { useProjectVisualizerStore } from '../../stores/useProjectVisualizerStore';
import { projectVisualizerApi } from '../../services/api';

const syntaxHighlight = (code) => {
  if (!code) return '';

  // Basic Regex highlighters
  let html = code
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

  // Keywords (cyan)
  const keywords = /\b(const|let|var|function|class|import|export|return|if|else|for|while|async|await|try|catch|switch|case|default|break|continue|new|this|typeof|instanceof)\b/g;
  html = html.replace(keywords, '<span class="text-cyan-400">$1</span>');

  // Strings (green)
  const strings = /(&quot;.*?&quot;|&#39;.*?&#39;|`.*?`)/g;
  html = html.replace(strings, '<span class="text-green-400">$1</span>');

  // Numbers (orange)
  const numbers = /\b(\d+)\b/g;
  html = html.replace(numbers, '<span class="text-orange-400">$1</span>');

  // Comments (muted)
  const comments = /(\/\/.*|\/\*[\s\S]*?\*\/)/g;
  html = html.replace(comments, '<span class="text-slate-500 italic">$1</span>');

  return html;
};

const EnhancedFileViewer = () => {
  const { selectedFile, sessionId, setInspectorOpen, setSelectedFile } = useProjectVisualizerStore();
  const [content, setContent] = useState('');
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!selectedFile || !sessionId) return;

    const fetchContent = async () => {
      setLoading(true);
      setError(null);
      try {
        const text = await projectVisualizerApi.getFileContent(sessionId, selectedFile.relativePath);
        setContent(text);
      } catch (err) {
        setError('Failed to load file content.');
        setContent('');
      } finally {
        setLoading(false);
      }
    };

    fetchContent();
  }, [selectedFile, sessionId]);

  const handleCopy = () => {
    navigator.clipboard.writeText(content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleBack = () => {
    setSelectedFile(null); // Goes back to module inspector if module was selected
  };

  if (!selectedFile) return null;

  return (
    <div className="flex flex-col h-full bg-[#0a0f1c]">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-white/10 bg-[#0f172a]">
        <div className="flex items-center gap-3 overflow-hidden">
          <button 
            onClick={handleBack}
            className="p-1 hover:bg-white/10 rounded mr-1 text-slate-400 hover:text-white"
            title="Back to Module"
          >
            <X className="w-5 h-5" />
          </button>
          <FileCode className="w-5 h-5 text-violet-400 shrink-0" />
          <div className="flex flex-col min-w-0">
            <h3 className="font-mono text-sm text-white truncate" title={selectedFile.fileName}>
              {selectedFile.fileName}
            </h3>
            <span className="text-xs text-slate-500 truncate" title={selectedFile.relativePath}>
              {selectedFile.relativePath}
            </span>
          </div>
        </div>

        <div className="flex items-center gap-2 shrink-0 ml-4">
          <button
            onClick={handleCopy}
            disabled={loading || !content}
            className="p-2 rounded hover:bg-white/10 text-slate-400 hover:text-white transition-colors"
          >
            {copied ? <Check className="w-4 h-4 text-green-400" /> : <Copy className="w-4 h-4" />}
          </button>
          <button
            onClick={() => setInspectorOpen(false)}
            className="p-2 rounded hover:bg-white/10 text-slate-400 hover:text-white transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-auto bg-[#050810] relative custom-scrollbar">
        {loading ? (
          <div className="absolute inset-0 flex items-center justify-center">
            <Loader2 className="w-8 h-8 animate-spin text-cyan-500" />
          </div>
        ) : error ? (
          <div className="p-6 text-red-400 font-medium text-sm flex items-center gap-2">
            <X className="w-4 h-4" /> {error}
          </div>
        ) : (
          <div className="flex text-sm font-mono leading-relaxed min-w-max">
            {/* Line Numbers */}
            <div className="flex flex-col items-end px-4 py-4 select-none border-r border-white/5 bg-[#0a0f1c] text-slate-600">
              {content.split('\n').map((_, i) => (
                <span key={i} className="px-1">{i + 1}</span>
              ))}
            </div>
            {/* Code */}
            <div className="px-4 py-4 text-slate-300">
              <pre dangerouslySetInnerHTML={{ __html: syntaxHighlight(content) }} />
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default EnhancedFileViewer;

import React, { useState, useMemo, useEffect } from 'react';
import { useProjectVisualizerStore } from '../../stores/useProjectVisualizerStore';
import { projectVisualizerApi } from '../../services/api';
import CodeViewer from './CodeViewer';
import { Folder, FolderOpen, FileCode, ChevronRight, ChevronDown, Loader2, Search, FileJson } from 'lucide-react';
import { cn } from '../../lib/utils';
import toast from 'react-hot-toast';

const buildFileTree = (nodes) => {
  const root = { name: 'root', type: 'folder', children: {}, path: '' };

  nodes.forEach(node => {
    const parts = node.id.split('/');
    let current = root;
    let currentPath = '';

    parts.forEach((part, i) => {
      currentPath += (currentPath ? '/' : '') + part;
      const isFile = i === parts.length - 1;

      if (!current.children[part]) {
        current.children[part] = {
          name: part,
          type: isFile ? 'file' : 'folder',
          path: currentPath,
          children: isFile ? null : {},
          data: isFile ? node.data : null
        };
      }
      current = current.children[part];
    });
  });

  return root;
};

const FileTreeNode = ({ node, level = 0, onSelect, selectedPath, expandedFolders, toggleFolder }) => {
  const isFolder = node.type === 'folder';
  const isExpanded = expandedFolders.has(node.path);
  const isSelected = selectedPath === node.path;

  if (node.name === 'root') {
    return (
      <div className="flex flex-col w-full">
        {Object.values(node.children)
          .sort((a, b) => {
            if (a.type !== b.type) return a.type === 'folder' ? -1 : 1;
            return a.name.localeCompare(b.name);
          })
          .map(child => (
            <FileTreeNode 
              key={child.path} 
              node={child} 
              level={0} 
              onSelect={onSelect}
              selectedPath={selectedPath}
              expandedFolders={expandedFolders}
              toggleFolder={toggleFolder}
            />
          ))}
      </div>
    );
  }

  return (
    <div className="flex flex-col w-full">
      <div 
        className={cn(
          "flex items-center gap-1.5 py-1 px-2 cursor-pointer transition-colors whitespace-nowrap",
          isSelected ? "bg-cyan-500/20 text-cyan-400" : "hover:bg-white/5 text-slate-300"
        )}
        style={{ paddingLeft: `${level * 12 + 8}px` }}
        onClick={() => isFolder ? toggleFolder(node.path) : onSelect(node)}
      >
        {isFolder ? (
          isExpanded ? <ChevronDown className="w-3.5 h-3.5 text-slate-400 shrink-0" /> : <ChevronRight className="w-3.5 h-3.5 text-slate-400 shrink-0" />
        ) : (
          <span className="w-3.5 h-3.5 shrink-0" /> // spacer
        )}

        {isFolder ? (
          isExpanded ? <FolderOpen className="w-4 h-4 text-violet-400 shrink-0" /> : <Folder className="w-4 h-4 text-violet-400 shrink-0" />
        ) : (
          <FileCode className="w-4 h-4 text-slate-400 shrink-0" />
        )}

        <span className="text-sm truncate">{node.name}</span>
      </div>

      {isFolder && isExpanded && node.children && (
        <div className="flex flex-col w-full">
          {Object.values(node.children)
            .sort((a, b) => {
              if (a.type !== b.type) return a.type === 'folder' ? -1 : 1;
              return a.name.localeCompare(b.name);
            })
            .map(child => (
              <FileTreeNode 
                key={child.path} 
                node={child} 
                level={level + 1} 
                onSelect={onSelect}
                selectedPath={selectedPath}
                expandedFolders={expandedFolders}
                toggleFolder={toggleFolder}
              />
            ))}
        </div>
      )}
    </div>
  );
};

const FileExplorer = () => {
  const { fileGraph, sessionId, setChatExpanded, addMessage, setChatMode } = useProjectVisualizerStore();
  const [expandedFolders, setExpandedFolders] = useState(new Set());
  const [selectedNode, setSelectedNode] = useState(null);
  const [fileContent, setFileContent] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [explanation, setExplanation] = useState(null);
  const [isExplaining, setIsExplaining] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const fileTree = useMemo(() => {
    if (!fileGraph || !fileGraph.nodes) return null;
    let nodes = fileGraph.nodes;
    if (searchQuery) {
      nodes = nodes.filter(n => n.id.toLowerCase().includes(searchQuery.toLowerCase()));
    }
    return buildFileTree(nodes);
  }, [fileGraph, searchQuery]);

  const toggleFolder = (path) => {
    const newExpanded = new Set(expandedFolders);
    if (newExpanded.has(path)) newExpanded.delete(path);
    else newExpanded.add(path);
    setExpandedFolders(newExpanded);
  };

  const handleSelect = async (node) => {
    setSelectedNode(node);
    setExplanation(null);
    try {
      setIsLoading(true);
      const content = await projectVisualizerApi.getFileContent(sessionId, node.path);
      setFileContent(content);
    } catch (e) {
      toast.error('Failed to load file content');
      setFileContent('// Error loading file content');
    } finally {
      setIsLoading(false);
    }
  };

  const handleExplain = async () => {
    if (!selectedNode) return;
    try {
      setIsExplaining(true);
      const result = await projectVisualizerApi.explainFile(sessionId, selectedNode.path);
      setExplanation(result);
    } catch (e) {
      toast.error('Failed to generate explanation');
    } finally {
      setIsExplaining(false);
    }
  };

  const startFileChat = () => {
    if (!selectedNode) return;
    setChatExpanded(true);
    setChatMode('qa');
    addMessage({ 
      role: 'user', 
      content: `[Context: I am looking at file '${selectedNode.path}']\nCan you explain this file in more detail?` 
    });
  };

  if (!fileTree) return null;

  return (
    <div className="flex h-full border border-white/10 rounded-2xl overflow-hidden bg-black/40">
      {/* Left Sidebar - File Tree */}
      <div className="w-80 shrink-0 border-r border-white/10 flex flex-col bg-[#0a0f1c]">
        <div className="p-3 border-b border-white/10">
          <div className="relative">
            <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
            <input 
              type="text" 
              placeholder="Search files..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full bg-white/5 border border-white/10 rounded-lg pl-9 pr-3 py-1.5 text-sm text-slate-200 outline-none focus:border-cyan-500/50"
            />
          </div>
        </div>
        <div className="flex-1 overflow-auto custom-scrollbar p-2">
          <FileTreeNode 
            node={fileTree} 
            onSelect={handleSelect} 
            selectedPath={selectedNode?.path}
            expandedFolders={expandedFolders}
            toggleFolder={toggleFolder}
          />
        </div>
      </div>

      {/* Right Area - Code & Explanation */}
      <div className="flex-1 flex flex-col md:flex-row h-full overflow-hidden">
        {selectedNode ? (
          <>
            <div className={cn("flex-1 h-full p-4 flex flex-col", explanation ? "md:w-2/3 border-r border-white/10" : "w-full")}>
              {isLoading ? (
                <div className="flex-1 flex items-center justify-center">
                  <Loader2 className="w-8 h-8 text-cyan-400 animate-spin" />
                </div>
              ) : (
                <CodeViewer 
                  code={fileContent} 
                  language={selectedNode.data?.language} 
                  fileName={selectedNode.path}
                  onExplain={handleExplain}
                />
              )}
            </div>

            {explanation && (
              <div className="md:w-1/3 w-full h-full bg-[#0a0f1c] overflow-y-auto custom-scrollbar border-t md:border-t-0 border-white/10 flex flex-col">
                <div className="p-4 border-b border-white/10 flex items-center justify-between sticky top-0 bg-[#0a0f1c]/95 backdrop-blur z-10">
                  <h3 className="font-semibold text-slate-200 flex items-center gap-2">
                    <FileJson className="w-4 h-4 text-violet-400" />
                    AI Explanation
                  </h3>
                  <button 
                    onClick={() => setExplanation(null)}
                    className="text-xs text-slate-400 hover:text-white"
                  >
                    Close
                  </button>
                </div>

                <div className="p-6 space-y-6">
                  {isExplaining ? (
                     <div className="flex flex-col items-center justify-center py-12 text-slate-400">
                       <Loader2 className="w-8 h-8 animate-spin text-violet-400 mb-4" />
                       <p>Analyzing file structure...</p>
                     </div>
                  ) : (
                    <>
                      <div>
                        <h4 className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">Purpose</h4>
                        <p className="text-sm text-slate-300 leading-relaxed">{explanation.purpose}</p>
                      </div>

                      {explanation.keyFunctions && (
                        <div>
                          <h4 className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">Key Functions</h4>
                          <ul className="space-y-2">
                            {Array.isArray(explanation.keyFunctions) 
                              ? explanation.keyFunctions.map((fn, i) => (
                                  <li key={i} className="text-sm text-slate-300 flex items-start gap-2">
                                    <span className="w-1.5 h-1.5 rounded-full bg-cyan-500/50 mt-1.5 shrink-0" />
                                    {fn}
                                  </li>
                                ))
                              : <p className="text-sm text-slate-300">{explanation.keyFunctions}</p>
                            }
                          </ul>
                        </div>
                      )}

                      {explanation.dependencies && (
                        <div>
                          <h4 className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">Dependencies</h4>
                          <p className="text-sm text-slate-300">{explanation.dependencies}</p>
                        </div>
                      )}

                      <div className="pt-4 border-t border-white/10">
                        <button 
                          onClick={startFileChat}
                          className="w-full py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-lg text-sm text-white transition-colors"
                        >
                          Chat about this file
                        </button>
                      </div>
                    </>
                  )}
                </div>
              </div>
            )}
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-slate-500">
            <FileCode className="w-16 h-16 mb-4 opacity-50" />
            <p>Select a file to view its code and AI explanation.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default FileExplorer;

import React, { useState, useEffect } from 'react';
import { useProjectVisualizerStore } from '../../stores/useProjectVisualizerStore';
import { projectVisualizerApi } from '../../services/api';
import { ShieldAlert, HelpCircle, Loader2, Play, Eye, EyeOff, BrainCircuit, RefreshCw } from 'lucide-react';
import { cn } from '../../lib/utils';
import { motion, AnimatePresence } from 'framer-motion';
import toast from 'react-hot-toast';

const InterviewPrep = () => {
  const { sessionId, setChatExpanded, setChatMode, addMessage } = useProjectVisualizerStore();
  const [questions, setQuestions] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [revealedAnswers, setRevealedAnswers] = useState(new Set());
  const [activeCategory, setActiveCategory] = useState(0);

  const fetchQuestions = async () => {
    setIsLoading(true);
    try {
      const data = await projectVisualizerApi.getInterviewQuestions(sessionId);
      if (data && data.categories) {
        setQuestions(data.categories);
      } else {
        toast.error('Invalid response format');
      }
    } catch (e) {
      toast.error('Failed to generate interview questions');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (!questions && !isLoading) {
      fetchQuestions();
    }
  }, []);

  const toggleAnswer = (idx) => {
    const newRevealed = new Set(revealedAnswers);
    if (newRevealed.has(idx)) newRevealed.delete(idx);
    else newRevealed.add(idx);
    setRevealedAnswers(newRevealed);
  };

  const startMockInterview = (questionStr) => {
    setChatExpanded(true);
    setChatMode('interview');
    addMessage({
      role: 'user',
      content: `I want to practice answering this question: "${questionStr}". Please evaluate my answer when I provide it.`
    });
  };

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center h-96">
        <Loader2 className="w-12 h-12 text-red-500 animate-spin mb-4" />
        <h2 className="text-xl font-bold text-white mb-2">Generating Interview Questions</h2>
        <p className="text-slate-400 max-w-md text-center">
          Analyzing the codebase architecture, modules, and identified risks to create tailored interview questions...
        </p>
      </div>
    );
  }

  if (!questions || questions.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-96">
        <ShieldAlert className="w-16 h-16 text-slate-500 mb-4" />
        <p className="text-slate-400 mb-4">No questions available.</p>
        <button 
          onClick={fetchQuestions}
          className="px-4 py-2 bg-white/10 hover:bg-white/20 rounded-lg text-white transition-colors"
        >
          Try Again
        </button>
      </div>
    );
  }

  const category = questions[activeCategory];

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-full max-w-7xl mx-auto w-full">
      {/* Sidebar */}
      <div className="w-full lg:w-64 shrink-0 flex flex-col gap-4">
        <div className="bg-[#0a0f1c] border border-white/10 rounded-2xl p-4">
          <div className="flex items-center justify-between mb-4 pb-4 border-b border-white/5">
            <h3 className="font-bold text-white flex items-center gap-2">
              <BrainCircuit className="w-5 h-5 text-red-400" />
              Categories
            </h3>
            <button 
              onClick={fetchQuestions}
              className="p-1.5 rounded-lg bg-white/5 hover:bg-white/10 text-slate-400 transition-colors"
              title="Regenerate Questions"
            >
              <RefreshCw className="w-4 h-4" />
            </button>
          </div>
          <div className="space-y-2">
            {questions.map((cat, i) => (
              <button
                key={i}
                onClick={() => setActiveCategory(i)}
                className={cn(
                  "w-full text-left px-3 py-2 rounded-lg text-sm transition-colors",
                  activeCategory === i 
                    ? "bg-red-500/10 text-red-400 font-medium border border-red-500/20" 
                    : "text-slate-400 hover:text-slate-200 hover:bg-white/5"
                )}
              >
                {cat.name}
              </button>
            ))}
          </div>
        </div>

        <div className="bg-red-500/5 border border-red-500/20 rounded-2xl p-4">
          <h4 className="font-semibold text-red-400 mb-2 flex items-center gap-2">
            <ShieldAlert className="w-4 h-4" />
            Interview Mode
          </h4>
          <p className="text-xs text-red-400/80 leading-relaxed mb-4">
            These questions are tailored specifically to this codebase. Use the Mock Interview feature to practice your answers against an elite Principal Engineer AI.
          </p>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 overflow-y-auto custom-scrollbar pr-2">
        <AnimatePresence mode="wait">
          <motion.div
            key={activeCategory}
            initial={{ opacity: 0, x: 10 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -10 }}
            transition={{ duration: 0.2 }}
            className="space-y-4"
          >
            <h2 className="text-2xl font-bold text-white mb-6 pb-4 border-b border-white/10">
              {category?.name}
            </h2>

            {category?.questions?.map((q, idx) => (
              <div key={idx} className="bg-[#0a0f1c] border border-white/10 rounded-2xl p-6 transition-colors hover:border-white/20">
                <div className="flex items-start justify-between gap-4 mb-4">
                  <h3 className="text-lg font-medium text-slate-200 leading-relaxed">
                    {q.question}
                  </h3>
                  <span className={cn(
                    "px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider shrink-0",
                    q.difficulty === 'hard' ? "bg-red-500/20 text-red-400 border border-red-500/20" :
                    q.difficulty === 'medium' ? "bg-amber-500/20 text-amber-400 border border-amber-500/20" :
                    "bg-emerald-500/20 text-emerald-400 border border-emerald-500/20"
                  )}>
                    {q.difficulty || 'medium'}
                  </span>
                </div>

                {q.hint && (
                  <div className="mb-6 p-3 rounded-xl bg-white/5 border border-white/10 flex gap-3 text-sm">
                    <HelpCircle className="w-5 h-5 text-violet-400 shrink-0" />
                    <p className="text-slate-400">{q.hint}</p>
                  </div>
                )}

                <div className="flex items-center gap-3 border-t border-white/5 pt-4 mt-4">
                  <button
                    onClick={() => toggleAnswer(idx)}
                    className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl text-sm font-medium text-slate-300 transition-colors"
                  >
                    {revealedAnswers.has(idx) ? (
                      <><EyeOff className="w-4 h-4" /> Hide Answer</>
                    ) : (
                      <><Eye className="w-4 h-4" /> Reveal Answer</>
                    )}
                  </button>
                  <button
                    onClick={() => startMockInterview(q.question)}
                    className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-red-500/10 hover:bg-red-500/20 border border-red-500/20 rounded-xl text-sm font-medium text-red-400 transition-colors"
                  >
                    <Play className="w-4 h-4" /> Start Mock Interview
                  </button>
                </div>

                {revealedAnswers.has(idx) && (
                  <motion.div
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: 'auto' }}
                    className="mt-4 p-4 rounded-xl bg-cyan-900/10 border border-cyan-500/20"
                  >
                    <h5 className="text-xs font-bold text-cyan-400 uppercase tracking-wider mb-2">Ideal Answer</h5>
                    <p className="text-slate-300 text-sm leading-relaxed whitespace-pre-wrap">
                      {q.idealAnswer}
                    </p>
                  </motion.div>
                )}
              </div>
            ))}
          </motion.div>
        </AnimatePresence>
      </div>
    </div>
  );
};

export default InterviewPrep;

import React, { useMemo } from 'react';
import { motion } from 'framer-motion';

const getLangColor = (lang) => {
  const map = {
    'JavaScript': '#f1e05a', 'JavaScript React': '#f1e05a',
    'TypeScript': '#3178c6', 'TypeScript React': '#3178c6',
    'Python': '#3572A5', 'Go': '#00ADD8', 'Rust': '#dea584',
    'Java': '#b07219', 'Ruby': '#701516', 'CSS': '#563d7c',
    'HTML': '#e34c26', 'PHP': '#4F5D95', 'C': '#555555',
    'C++': '#f34b7d', 'Swift': '#F05138', 'JSON': '#292929',
    'Markdown': '#083fa1', 'Shell': '#89e051'
  };
  return map[lang] || '#8b5cf6'; // fallback to violet
};

const LanguageBar = ({ languages }) => {
  const languageData = useMemo(() => {
    if (!languages) return [];

    // languages might be a Map or a plain object depending on how it serializes
    let entries = [];
    if (languages instanceof Map) {
      entries = Array.from(languages.entries());
    } else if (typeof languages === 'object') {
      entries = Object.entries(languages);
    }

    const total = entries.reduce((sum, [_, loc]) => sum + loc, 0);

    if (total === 0) return [];

    return entries
      .map(([lang, loc]) => ({
        lang,
        loc,
        pct: (loc / total) * 100,
        color: getLangColor(lang)
      }))
      .sort((a, b) => b.loc - a.loc); // sort largest first
  }, [languages]);

  if (languageData.length === 0) return null;

  return (
    <div className="w-full">
      {/* The Bar */}
      <div className="h-3 w-full rounded-full overflow-hidden flex bg-slate-800 border border-slate-700/50 shadow-inner">
        {languageData.map((data, i) => (
          <motion.div
            key={data.lang}
            initial={{ width: 0 }}
            animate={{ width: `${Math.max(data.pct, 0.5)}%` }} // Ensure visible even if small
            transition={{ duration: 1, delay: 0.5 + (i * 0.1) }}
            className="h-full relative group cursor-pointer"
            style={{ backgroundColor: data.color }}
          >
            {/* Tooltip */}
            <div className="absolute -top-10 left-1/2 -translate-x-1/2 bg-black text-white text-xs py-1 px-2 rounded opacity-0 group-hover:opacity-100 pointer-events-none whitespace-nowrap z-50 transition-opacity">
              {data.lang} • {data.pct.toFixed(1)}% ({data.loc.toLocaleString()} LOC)
            </div>
          </motion.div>
        ))}
      </div>

      {/* Legend */}
      <div className="flex flex-wrap gap-4 mt-3">
        {languageData.filter(d => d.pct >= 1).map((data) => (
          <div key={data.lang} className="flex items-center gap-1.5 text-xs text-slate-300">
            <span 
              className="w-2.5 h-2.5 rounded-full shadow-sm"
              style={{ backgroundColor: data.color }}
            />
            <span className="font-medium">{data.lang}</span>
            <span className="text-slate-500">{data.pct.toFixed(1)}%</span>
          </div>
        ))}
        {languageData.some(d => d.pct < 1) && (
          <div className="text-xs text-slate-500 flex items-center">
            + others
          </div>
        )}
      </div>
    </div>
  );
};

export default LanguageBar;

