import { useState, useEffect } from 'react'
import { account } from '../config/appwrite'
import { ID, OAuthProvider } from 'appwrite'
import { AuthContext } from './AuthContext'
import { authApi } from '../services/api'

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const initAuth = async () => {
      try {
        const sessionUser = await account.get()
        if (sessionUser) {
          try {
            // Check admin status from our backend
            const response = await authApi.getProfile()
            if (response?.success && response?.user) {
              sessionUser.isAdmin = !!response.user.isAdmin
              if (response.user.name) {
                sessionUser.displayName = response.user.name
              } else {
                sessionUser.displayName = sessionUser.name
              }
            } else {
              sessionUser.isAdmin = false
              sessionUser.displayName = sessionUser.name
            }
          } catch (error) {
            console.error('Failed to fetch user profile for admin check:', error)
            sessionUser.isAdmin = false
            sessionUser.displayName = sessionUser.name
          }
          // Appwrite uses $id, Firebase used uid. Polyfill for compatibility:
          sessionUser.uid = sessionUser.$id
          setUser(sessionUser)
        }
      } catch (err) {
        // Not logged in
        setUser(null)
      } finally {
        setLoading(false)
      }
    }

    initAuth()
  }, [])

  const signup = async (email, password, displayName) => {
    // Create the user
    await account.create(ID.unique(), email, password, displayName)
    // Log them in immediately
    await account.createEmailPasswordSession(email, password)

    // Fetch and set the user
    const sessionUser = await account.get()
    sessionUser.uid = sessionUser.$id
    sessionUser.displayName = sessionUser.name
    setUser(sessionUser)
    return sessionUser
  }

  const login = async (email, password) => {
    await account.createEmailPasswordSession(email, password)
    const sessionUser = await account.get()
    sessionUser.uid = sessionUser.$id
    sessionUser.displayName = sessionUser.name
    setUser(sessionUser)
    return sessionUser
  }

  const loginWithGoogle = async () => {
    const apiUrl = window.location.origin
    account.createOAuth2Session(OAuthProvider.Google, `${apiUrl}/`, `${apiUrl}/login`)
  }

  const loginWithLinkedIn = () => {
    const apiUrl = import.meta.env.VITE_API_URL || 'http://localhost:5000'
    window.location.href = `${apiUrl}/api/auth/linkedin`
  }

  const loginWithGitHub = async () => {
    const apiUrl = window.location.origin
    account.createOAuth2Session(OAuthProvider.Github, `${apiUrl}/`, `${apiUrl}/login`)
  }

  const logout = async () => {
    try {
      await account.deleteSession('current')
    } catch(err) {
      console.warn("No active session to delete")
    }
    setUser(null)
  }

  const getToken = async () => {
    if (!user) return null
    try {
      const jwt = await account.createJWT()
      return jwt.jwt
    } catch (err) {
      console.error("Failed to get JWT", err)
      return null
    }
  }

  const value = {
    user,
    loading,
    isAdmin: loading ? undefined : (user?.isAdmin ?? false),
    signup,
    login,
    loginWithGoogle,
    loginWithLinkedIn,
    loginWithGitHub,
    logout,
    getToken,
    isMockAuth: false
  }

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  )
}

import React, { createContext, useContext, useMemo } from 'react';
import dummyData from '../data/dummy_data.json';

export const PortfolioContext = createContext({
  portfolioData: dummyData,
  dummyData,
});

export function normalizePortfolioData(portfolioData = {}) {
  const source = portfolioData && Object.keys(portfolioData).length ? portfolioData : dummyData;

  const personal = {
    ...dummyData.personal,
    ...source.personal,
    ...(source.hero?.subtitle && { name: source.hero.subtitle }),
    ...(source.hero?.title && { title: source.hero.title }),
    ...(source.hero?.tagline && { tagline: source.hero.tagline }),
    ...(source.about?.bio && { bio: source.about.bio }),
  };

  const skills = Array.isArray(source.skills) && source.skills.length
    ? source.skills.map((skill, index) => (
        typeof skill === 'string'
          ? {
              name: skill,
              level: 72 + ((index * 7) % 24),
              category: 'Core',
            }
          : skill
      ))
    : dummyData.skills;

  const projects = Array.isArray(source.projects) && source.projects.length
    ? source.projects.map((project, index) => ({
        ...project,
        title: project.title || project.name || dummyData.projects[index % dummyData.projects.length].title,
        description: project.description || project.summary || dummyData.projects[index % dummyData.projects.length].description,
        techStack: project.techStack || project.technologies || project.tech || dummyData.projects[index % dummyData.projects.length].techStack,
        image: project.image || dummyData.projects[index % dummyData.projects.length].image,
      }))
    : dummyData.projects;

  return {
    ...dummyData,
    ...source,
    personal,
    socials: {
      ...dummyData.socials,
      ...source.socials,
      ...source.contact,
    },
    stats: {
      ...dummyData.stats,
      ...source.stats,
    },
    skills,
    projects,
    experience: Array.isArray(source.experience) && source.experience.length ? source.experience : dummyData.experience,
    testimonials: Array.isArray(source.testimonials) && source.testimonials.length ? source.testimonials : dummyData.testimonials,
  };
}

export function PortfolioProvider({ children, portfolioData }) {
  const value = useMemo(() => {
    const normalized = normalizePortfolioData(portfolioData);
    return {
      portfolioData: normalized,
      dummyData,
    };
  }, [portfolioData]);

  return (
    <PortfolioContext.Provider value={value}>
      {children}
    </PortfolioContext.Provider>
  );
}

export function usePortfolio() {
  return useContext(PortfolioContext);
}

import { createContext, useContext, useMemo } from 'react'
import dummy from '../data/dummy_resume.json'

/**
 * Resume data context.
 *
 * Mirrors PortfolioContext.jsx — normalizes a variety of input shapes (AI
 * extractor output, ResumeBuilder form state, saved resume text, AI draft
 * from localStorage) into the canonical resume shape that all 5 templates
 * consume via `useResume()`.
 *
 * Canonical shape:
 *   {
 *     personal:    { name, title, summary, email, phone, location,
 *                    website, linkedin, github, photo },
 *     experience:  [{ role, company, period, location, bullets[] }],
 *     education:   [{ degree, institution, period, location, description }],
 *     projects:    [{ title, description, techStack[], link }],
 *     skills:      [{ name, level, category }],
 *     certifications: [{ name, issuer, year }],
 *     sectionOrder:   [String]  // drag-and-drop order of body sections
 *     customSections: [{ id, title, kind, items[], body, order }]
 *   }
 */

const FALLBACK = dummy

const ResumeContext = createContext(null)

export function ResumeProvider({ value, children }) {
  // Memoize so referential equality holds across re-renders unless data changes.
  const memo = useMemo(() => normalizeResumeData(value), [value])
  return (
    <ResumeContext.Provider value={memo}>{children}</ResumeContext.Provider>
  )
}

export function useResume() {
  const ctx = useContext(ResumeContext)
  if (!ctx) {
    // Allow components to render outside a provider by falling back to dummy data
    // (useful for storybook-style previews and lazy-loaded templates).
    return FALLBACK
  }
  return ctx
}

// ─── Normalization helpers ────────────────────────────────────────────────────

function asString(v, fallback = '') {
  if (v === null || v === undefined) return fallback
  return String(v).trim()
}

function pickPeriod(item = {}) {
  if (item.period) return asString(item.period)
  if (item.duration) return asString(item.duration)
  if (item.year) return asString(item.year)
  if (item.startDate || item.endDate) {
    const s = item.startDate ? asString(item.startDate) : ''
    const e = item.endDate ? asString(item.endDate) : (item.current ? 'Present' : '')
    if (s && e) return `${s} – ${e}`
    return s || e
  }
  return ''
}

function splitBullets(input) {
  if (Array.isArray(input)) return input.filter(Boolean).map(asString)
  if (typeof input !== 'string' || !input.trim()) return []
  // Split on newline OR " • " OR " - " OR " * " so multi-line descriptions
  // (e.g. from the AI extractor) become bullet items automatically.
  return input
    .split(/\r?\n|(?:^|\s)[•\-*]\s+/)
    .map(s => s.trim())
    .filter(Boolean)
}

function normalizeSkill(s) {
  if (typeof s === 'string') return { name: s, level: '', category: '' }
  if (s && typeof s === 'object') {
    return {
      name: asString(s.name || s.title),
      level: asString(s.level || s.rating),
      category: asString(s.category || s.type),
    }
  }
  return { name: '', level: '', category: '' }
}

function normalizeExperience(item = {}) {
  if (typeof item === 'string') return { description: item }
  return {
    role: asString(item.role || item.title || item.position),
    company: asString(item.company || item.organization || item.employer),
    period: pickPeriod(item),
    location: asString(item.location),
    bullets: splitBullets(item.bullets || item.description || item.highlights),
  }
}

function normalizeProject(item = {}) {
  if (typeof item === 'string') return { title: item }
  return {
    title: asString(item.title || item.name),
    description: asString(item.description || item.summary),
    techStack: Array.isArray(item.techStack)
      ? item.techStack.map(asString).filter(Boolean)
      : Array.isArray(item.technologies)
      ? item.technologies.map(asString).filter(Boolean)
      : Array.isArray(item.tech)
      ? item.tech.map(asString).filter(Boolean)
      : [],
    link: asString(item.link || item.url || item.liveUrl || item.githubUrl),
  }
}

function normalizeEducation(item = {}) {
  return {
    degree: asString(item.degree || item.title),
    institution: asString(item.institution || item.school || item.university),
    period: pickPeriod(item),
    location: asString(item.location),
    description: asString(item.description),
  }
}

function normalizeCertification(item = {}) {
  return {
    name: asString(item.name || item.title),
    issuer: asString(item.issuer || item.organization),
    year: asString(item.year || item.date),
  }
}

// Mirrors backend/src/models/Resume.model.js customSections schema.
const CUSTOM_SECTION_KINDS = ['list', 'paragraph', 'books', 'quotes']

function normalizeCustomSection(item, index = 0) {
  if (!item || typeof item !== 'object') return null
  const kind = CUSTOM_SECTION_KINDS.includes(item.kind) ? item.kind : 'list'
  return {
    id: asString(item.id) || `custom-${index}`,
    title: asString(item.title),
    kind,
    items: Array.isArray(item.items) ? item.items.map(asString).filter(Boolean) : [],
    body: asString(item.body),
    order: Number.isFinite(item.order) ? item.order : index,
  }
}

function normalizePersonal(p = {}, fallback = {}) {
  const src = { ...fallback, ...p }
  return {
    name: asString(src.name || src.fullName),
    title: asString(src.title || src.headline),
    summary: asString(src.summary || src.bio || src.tagline),
    email: asString(src.email),
    phone: asString(src.phone),
    location: asString(src.location || src.address),
    website: asString(src.website || src.portfolio || src.url),
    linkedin: asString(src.linkedin),
    github: asString(src.github),
    photo: asString(src.photo || src.avatar || src.avatarUrl),
  }
}

// ─── Top-level shape detection ────────────────────────────────────────────────

/**
 * Detect whether `raw` matches the AI portfolio-extractor output shape
 * (hero / contact / about / experience / projects / skills).
 */
function fromAiExtractor(raw) {
  return Boolean(raw && (raw.hero || raw.contact || raw.about))
}

/**
 * @param {object|null|undefined} raw
 * @returns {object} The canonical resume shape
 */
export function normalizeResumeData(raw) {
  const fbPersonal = { photo: '', ...(FALLBACK.personal || {}) }
  const personal = normalizePersonal(raw?.personal || {}, fbPersonal)

  // Merge in social-links from portfolio/socials if explicit fields missing
  const socials = raw?.socials || {}
  if (!personal.email && raw?.contact?.email) personal.email = raw.contact.email
  if (!personal.phone && raw?.contact?.phone) personal.phone = raw.contact.phone
  if (!personal.linkedin && (socials.linkedin || raw?.contact?.linkedin))
    personal.linkedin = socials.linkedin || raw.contact.linkedin
  if (!personal.github && (socials.github || raw?.contact?.github))
    personal.github = socials.github || raw.contact.github
  if (!personal.website && (socials.portfolio || raw?.contact?.portfolio))
    personal.website = socials.portfolio || raw.contact.portfolio

  // Backfill personal from AI extractor hero/about blocks
  if (fromAiExtractor(raw) && !raw.personal) {
    if (!personal.name && raw.hero?.subtitle) personal.name = raw.hero.subtitle
    if (!personal.title && raw.hero?.title) personal.title = raw.hero.title
    if (!personal.summary && raw.about?.bio) personal.summary = raw.about.bio
  }

  const experience = Array.isArray(raw?.experience)
    ? raw.experience.map(normalizeExperience).filter(e => e.role || e.company || e.bullets.length)
    : []

  const education = Array.isArray(raw?.education)
    ? raw.education.map(normalizeEducation).filter(e => e.degree || e.institution)
    : []

  const projects = Array.isArray(raw?.projects)
    ? raw.projects.map(normalizeProject).filter(p => p.title || p.description)
    : []

  const skills = Array.isArray(raw?.skills)
    ? raw.skills.map(normalizeSkill).filter(s => s.name)
    : []

  const certifications = Array.isArray(raw?.certifications)
    ? raw.certifications.map(normalizeCertification).filter(c => c.name)
    : []

  // Layout controls (Gap #9). Accepts the same shape as DEFAULT_LAYOUT,
  // or undefined. Caller can override via ResumeProvider value.layout.
  const layout = { ...DEFAULT_LAYOUT, ...(raw?.layout || {}) }

  // Drag-and-drop section order + user-defined custom sections. Both are
  // optional; templates that honor ordering read these via <OrderedSections>.
  // An absent/partial sectionOrder degrades to each template's default order,
  // so templates that don't consume it are unaffected.
  const sectionOrder = Array.isArray(raw?.sectionOrder)
    ? [...new Set(raw.sectionOrder.map((v) => asString(v)).filter(Boolean))]
    : []

  const customSections = Array.isArray(raw?.customSections)
    ? raw.customSections
        .map(normalizeCustomSection)
        .filter(s => s && (s.title || s.items.length || s.body))
        .sort((a, b) => a.order - b.order)
    : []

  return {
    personal,
    experience,
    education,
    projects,
    skills,
    certifications,
    layout,
    sectionOrder,
    customSections,
  }
}

const DEFAULT_LAYOUT = {
  pageSize: 'A4',
  fontSize: 'Medium',
  fontSizePx: '14px',
  spacing: 'Comfortable',
  lineHeight: 1.5,
}

export { FALLBACK as RESUME_FALLBACK, DEFAULT_LAYOUT }

import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../hooks/useAuth';
import { initializeSocket, disconnectSocket, getSocket, socketEvents } from '../services/socket';
import { SocketContext } from './SocketContext';

/**
 * Provider component that handles real-time web socket connections,
 * status updates of online users, and push notifications.
 *
 * @param {object} props - The component props.
 * @param {React.ReactNode} props.children - The children elements.
 * @returns {React.JSX.Element} The rendered Provider component.
 */
export function SocketProvider({ children }) {
  const { user } = useAuth();
  const [socket, setSocket] = useState(null);
  const [isConnected, setIsConnected] = useState(false);
  const [onlineUsers, setOnlineUsers] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const unreadCount = notifications.filter((n) => !n.read).length;


  /**
   * Pushes a new notification to the state stack.
   *
   * @param {string} type - The notification type.
   * @param {object} data - Metadata payload of the notification.
   */
  const pushNotification = useCallback((type, data) => {
    setNotifications((prev) =>
      [
        {
          id: `${type}-${Date.now()}-${Math.random()}`,
          type,
          data,
          read: false,
          timestamp: new Date(),
        },
        ...prev,
      ].slice(0, 50)
    );
  }, []);

  /**
   * Marks a specific notification as read.
   *
   * @param {string} id - The notification ID.
   */
  const markRead = useCallback((id) => {
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
    );
  }, []);

  /**
   * Marks all notifications as read.
   */
  const markAllRead = useCallback(() => {
    setNotifications((prev) =>
     prev.map((n) => ({ ...n, read: true }))
    );
  }, []);

  /**
   * Dismisses a specific notification.
   *
   * @param {string} id - The notification ID.
   */
  const dismissNotification = useCallback((id) => {
    setNotifications((prev) =>
      prev.filter((n) => n.id !== id)
    );
  }, []);

  /**
   * Clears all notifications.
   */
  const clearNotifications = useCallback(() => {
    setNotifications([]);
  }, []);

  // Initialize socket when user logs in
  useEffect(() => {
    let mounted = true;
    let cleanupHandlers = () => {};

    const setupSocket = async () => {
      if (user) {
        const socketInstance = await initializeSocket();
        if (mounted && socketInstance) {
          setSocket(socketInstance);

          const handleConnect = () => setIsConnected(true);
          const handleDisconnect = () => setIsConnected(false);
          const handleOnlineUsers = ({ users }) => setOnlineUsers(users);
          const handleUserOnline = ({ uid, name }) => {
            setOnlineUsers(prev => {
              if (!prev.some(u => u.uid === uid)) {
                return [...prev, { uid, name, status: 'online' }];
              }
              return prev;
            });
          };
          const handleUserOffline = ({ uid }) => {
            setOnlineUsers(prev => prev.filter(u => u.uid !== uid));
          };
          const handleStatusChanged = ({ uid, status }) => {
            setOnlineUsers(prev =>
              prev.map(u => u.uid === uid ? { ...u, status } : u)
            );
          };


          const handleNotification = (data) =>
            pushNotification('notification', data);

          const handleJobAlertNewJobs = (data) =>
             pushNotification('job_alert_new_jobs', data);

          const handleJobAlertEmailSent = (data) =>
            pushNotification('job_alert_email_sent', data);

          const handleJobAlertEmailFailed = (data) =>
            pushNotification('job_alert_email_failed', data);

          socketInstance.on('connect', handleConnect);
          socketInstance.on('disconnect', handleDisconnect);
          socketInstance.on('online_users', handleOnlineUsers);
          socketInstance.on('user_online', handleUserOnline);
          socketInstance.on('user_offline', handleUserOffline);
          socketInstance.on('user_status_changed', handleStatusChanged);
          socketInstance.on('notification', handleNotification);
          socketInstance.on('job_alert_new_jobs', handleJobAlertNewJobs);
          socketInstance.on('job_alert_email_sent', handleJobAlertEmailSent);
          socketInstance.on('job_alert_email_failed', handleJobAlertEmailFailed);

          if (socketInstance.connected) handleConnect();

          cleanupHandlers = () => {
            socketInstance.off('connect', handleConnect);
            socketInstance.off('disconnect', handleDisconnect);
            socketInstance.off('online_users', handleOnlineUsers);
            socketInstance.off('user_online', handleUserOnline);
            socketInstance.off('user_offline', handleUserOffline);
            socketInstance.off('user_status_changed', handleStatusChanged);
            socketInstance.off('notification', handleNotification);
            socketInstance.off('job_alert_new_jobs', handleJobAlertNewJobs);
            socketInstance.off('job_alert_email_sent', handleJobAlertEmailSent);
            socketInstance.off('job_alert_email_failed', handleJobAlertEmailFailed);
          };

          // Get initial online users
          socketEvents.getOnlineUsers();
        }
      } else {
        disconnectSocket();
        setSocket(null);
        setIsConnected(false);
        setOnlineUsers([]);
        setNotifications([]);
      }
    };

    setupSocket();

    return () => {
      mounted = false;
      cleanupHandlers();
      if (!user) {
        disconnectSocket();
      }
    };
  }, [user]);

  /**
   * Subscribes to a socket event with a callback, returning an unsubscribe cleanup function.
   *
   * @param {string} event - The socket event name.
   * @param {Function} callback - The event handler callback function.
   * @returns {Function} An unsubscribe function to remove the listener.
   */
  const subscribe = useCallback((event, callback) => {
    const currentSocket = getSocket();
    if (currentSocket) {
      currentSocket.on(event, callback);
      return () => currentSocket.off(event, callback);
    }
    return () => {};
  }, [socket]);

  /**
   * Emits a socket event with data to the server.
   *
   * @param {string} event - The socket event name.
   * @param {object} data - The message payload to emit.
   */
  const emit = useCallback((event, data) => {
    const currentSocket = getSocket();
    if (currentSocket?.connected) {
      currentSocket.emit(event, data);
    }
  }, [socket]);

  const value = {
    socket,
    isConnected,
    onlineUsers,
    notifications,
    unreadCount,
    markRead,
    markAllRead,
    dismissNotification,
    clearNotifications,
    subscribe,
    emit,
    ...socketEvents
  };

  return (
    <SocketContext.Provider value={value}>
      {children}
    </SocketContext.Provider>
  );
}

import { useState, useEffect, useRef, useCallback } from 'react';

let faceLandmarksDetectionPromise = null;

const loadTensorFlow = async () => {
    if (!faceLandmarksDetectionPromise) {
        faceLandmarksDetectionPromise = (async () => {
            const tf = await import('@tensorflow/tfjs');
            const fld = await import('@tensorflow-models/face-landmarks-detection');
            await tf.ready();
            return fld;
        })();
    }
    return faceLandmarksDetectionPromise;
};

const calculateConfidenceMetrics = (predictions, frameWidth = 640, frameHeight = 480) => {
    if (!predictions || predictions.length === 0) {
        return {
            faceDetected: false,
            confidence: 0,
            eyeContact: 0,
            headStability: 0,
            overallScore: 0
        };
    }

    const face = predictions[0];
    const keypoints = face.keypoints;

    const leftEye = keypoints.filter(k => k.name?.includes('leftEye'));
    const rightEye = keypoints.filter(k => k.name?.includes('rightEye'));
    const nose = keypoints.find(k => k.name === 'noseTip');

    let eyeContact = 70;
    if (leftEye.length > 0 && rightEye.length > 0) {
        const leftCenter = leftEye.reduce((acc, p) => ({ x: acc.x + p.x, y: acc.y + p.y }), { x: 0, y: 0 });
        const rightCenter = rightEye.reduce((acc, p) => ({ x: acc.x + p.x, y: acc.y + p.y }), { x: 0, y: 0 });
        leftCenter.x /= leftEye.length;
        leftCenter.y /= leftEye.length;
        rightCenter.x /= rightEye.length;
        rightCenter.y /= rightEye.length;

        const eyeDistance = Math.abs(rightCenter.x - leftCenter.x);
        const eyeSymmetry = Math.abs(leftCenter.y - rightCenter.y);
        eyeContact = Math.min(100, Math.max(0, 100 - eyeSymmetry * 2));
    }

    let headStability = 80;
    if (nose) {
        const centerX = frameWidth / 2;
        const centerY = frameHeight / 2;
        const deviation = Math.sqrt(Math.pow(nose.x - centerX, 2) + Math.pow(nose.y - centerY, 2));
        headStability = Math.max(0, 100 - deviation * 0.3);
    }

    const confidence = face.box ? Math.min(100, (face.box.width * face.box.height) / 500) : 70;

    const overallScore = Math.round((eyeContact * 0.3) + (headStability * 0.3) + (confidence * 0.4));

    return {
        faceDetected: true,
        confidence: Math.round(confidence),
        eyeContact: Math.round(eyeContact),
        headStability: Math.round(headStability),
        overallScore
    };
};

export const useFaceDetection = (videoRef, isActive = false) => {
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);
    const [metrics, setMetrics] = useState({
        faceDetected: false,
        confidence: 0,
        eyeContact: 0,
        headStability: 0,
        overallScore: 0
    });
    const [modelReady, setModelReady] = useState(false);

    const detectorRef = useRef(null);
    const animationFrameRef = useRef(null);
    const metricsHistoryRef = useRef([]);

    const initializeDetector = useCallback(async () => {
        try {
            setIsLoading(true);
            setError(null);

            const fld = await loadTensorFlow();
            const model = fld.SupportedModels.MediaPipeFaceMesh;
            const detectorConfig = {
                runtime: 'tfjs',
                refineLandmarks: true,
                maxFaces: 1
            };

            detectorRef.current = await fld.createDetector(model, detectorConfig);
            setModelReady(true);
            setIsLoading(false);
        } catch (err) {
            console.error('Failed to initialize face detector:', err);
            setError('Failed to load face detection model');
            setIsLoading(false);
        }
    }, []);

    const detectFace = useCallback(async () => {
        if (!detectorRef.current || !videoRef.current || !isActive) return;

        const video = videoRef.current;
        if (video.readyState < 2) {
            animationFrameRef.current = requestAnimationFrame(detectFace);
            return;
        }

        try {
            const predictions = await detectorRef.current.estimateFaces(video, { flipHorizontal: true });
            const frameWidth = video.videoWidth || video.clientWidth || 640;
            const frameHeight = video.videoHeight || video.clientHeight || 480;
            const newMetrics = calculateConfidenceMetrics(predictions, frameWidth, frameHeight);

            metricsHistoryRef.current.push(newMetrics);
            if (metricsHistoryRef.current.length > 30) {
                metricsHistoryRef.current.shift();
            }

            setMetrics(newMetrics);
        } catch (err) {
            console.error('Face detection error:', err);
        }

        animationFrameRef.current = requestAnimationFrame(detectFace);
    }, [videoRef, isActive]);

    const getAverageMetrics = useCallback(() => {
        const history = metricsHistoryRef.current;
        if (history.length === 0) {
            return { averageConfidence: 0, eyeContactPercentage: 0, headMovementStability: 0, overallExpressionScore: 0 };
        }

        const validHistory = history.filter(m => m.faceDetected);
        if (validHistory.length === 0) {
            return { averageConfidence: 0, eyeContactPercentage: 0, headMovementStability: 0, overallExpressionScore: 0 };
        }

        return {
            averageConfidence: Math.round(validHistory.reduce((sum, m) => sum + m.confidence, 0) / validHistory.length),
            eyeContactPercentage: Math.round(validHistory.reduce((sum, m) => sum + m.eyeContact, 0) / validHistory.length),
            headMovementStability: Math.round(validHistory.reduce((sum, m) => sum + m.headStability, 0) / validHistory.length),
            overallExpressionScore: Math.round(validHistory.reduce((sum, m) => sum + m.overallScore, 0) / validHistory.length)
        };
    }, []);

    const resetMetrics = useCallback(() => {
        metricsHistoryRef.current = [];
        setMetrics({ faceDetected: false, confidence: 0, eyeContact: 0, headStability: 0, overallScore: 0 });
    }, []);

    useEffect(() => {
        initializeDetector();

        return () => {
            if (animationFrameRef.current) {
                cancelAnimationFrame(animationFrameRef.current);
            }
            if (detectorRef.current) {
                detectorRef.current.dispose?.();
            }
        };
    }, [initializeDetector]);

    useEffect(() => {
        if (isActive && modelReady) {
            detectFace();
        } else if (animationFrameRef.current) {
            cancelAnimationFrame(animationFrameRef.current);
        }

        return () => {
            if (animationFrameRef.current) {
                cancelAnimationFrame(animationFrameRef.current);
            }
        };
    }, [isActive, modelReady, detectFace]);

    return {
        isLoading,
        error,
        metrics,
        modelReady,
        getAverageMetrics,
        resetMetrics
    };
};

export default useFaceDetection;

/**
 * useVoiceToText — Reusable hook for Web Speech API voice-to-text.
 *
 * Implements issue #28: Voice-to-Text for Mock Interviews
 *
 * Features:
 *  - Browser / device compatibility detection
 *  - interim + final transcript accumulation
 *  - Auto-restart on network/no-speech errors
 *  - Language selection support
 *  - Exposes isListening, transcript, interimTranscript, error, isSupported
 */
import { useState, useRef, useCallback, useEffect } from 'react';

/**
 * Returns true when the Web Speech API is available in the current browser.
 */
export const isSpeechRecognitionSupported = () =>
    typeof window !== 'undefined' && !!(window.SpeechRecognition || window.webkitSpeechRecognition);

/**
 * @param {object} options
 * @param {string}   [options.lang='en-US']        BCP-47 language tag
 * @param {boolean}  [options.continuous=true]      Keep listening until stopped
 * @param {boolean}  [options.interimResults=true]  Emit interim (non-final) results
 * @param {Function} [options.onFinalTranscript]    Called with the accumulated final string
 * @param {Function} [options.onError]              Called with an error message string
 */
export function useVoiceToText({
    lang = 'en-US',
    continuous = true,
    interimResults = true,
    onFinalTranscript,
    onError,
} = {}) {
    const [isListening, setIsListening] = useState(false);
    const [transcript, setTranscript] = useState('');           // final only
    const [interimTranscript, setInterimTranscript] = useState(''); // live preview
    const [error, setError] = useState('');
    const [isSupported] = useState(isSpeechRecognitionSupported);

    const recognitionRef = useRef(null);
    const isListeningRef = useRef(false);
    const finalAccumulatorRef = useRef('');

    // Sync ref so event handlers always see current value
    useEffect(() => {
        isListeningRef.current = isListening;
    }, [isListening]);

    const stopListening = useCallback(() => {
        isListeningRef.current = false;
        setIsListening(false);
        setInterimTranscript('');

        if (recognitionRef.current) {
            try { recognitionRef.current.stop(); } catch (_) { /* ignore */ }
            recognitionRef.current = null;
        }
    }, []);

    const startListening = useCallback(() => {
        if (!isSupported) {
            const msg = 'Speech recognition is not supported in this browser. Please use Chrome or Edge.';
            setError(msg);
            onError?.(msg);
            return;
        }

        if (isListeningRef.current || recognitionRef.current) {
            return; // Prevent duplicate instances on rapid re-entry
        }

        // Reset state
        finalAccumulatorRef.current = '';
        setTranscript('');
        setInterimTranscript('');
        setError('');
        isListeningRef.current = true;
        setIsListening(true);

        const SpeechRec = window.SpeechRecognition || window.webkitSpeechRecognition;
        const recognition = new SpeechRec();
        recognition.lang = lang;
        recognition.continuous = continuous;
        recognition.interimResults = interimResults;

        recognition.onresult = (event) => {
            let finalChunk = '';
            let interim = '';

            for (let i = event.resultIndex; i < event.results.length; i++) {
                const result = event.results[i];
                if (result.isFinal) {
                    finalChunk += result[0].transcript + ' ';
                } else {
                    interim += result[0].transcript;
                }
            }

            if (finalChunk) {
                finalAccumulatorRef.current += finalChunk;
                setTranscript(finalAccumulatorRef.current);
                onFinalTranscript?.(finalAccumulatorRef.current);
            }
            setInterimTranscript(interim);
        };

        recognition.onerror = (event) => {
            // Auto-restart on transient errors
            const transient = ['no-speech', 'network', 'aborted'];
            if (isListeningRef.current && transient.includes(event.error)) {
                setTimeout(() => {
                    try { recognition.start(); } catch (_) { /* ignore */ }
                }, 150);
                return;
            }

            const messages = {
                'not-allowed': 'Microphone access denied. Please allow microphone permission in your browser settings.',
                'service-not-allowed': 'Speech service blocked. Try Chrome or Edge on desktop.',
                'audio-capture': 'No microphone detected. Please connect a microphone and try again.',
                'language-not-supported': `Language "${lang}" is not supported by your browser's speech recognition.`,
            };
            const msg = messages[event.error] || `Speech recognition error: ${event.error}`;
            setError(msg);
            onError?.(msg);
            stopListening();
        };

        recognition.onend = () => {
            if (isListeningRef.current) {
                if (continuous) {
                    // Auto-restart if continuous
                    setTimeout(() => {
                        if (!isListeningRef.current || recognitionRef.current !== recognition) return;
                        try { recognition.start(); } catch (_) { /* ignore */ }
                    }, 150);
                } else {
                    stopListening();
                }
            }
        };

        recognitionRef.current = recognition;

        try {
            recognition.start();
        } catch (err) {
            const msg = `Failed to start speech recognition: ${err.message}`;
            setError(msg);
            onError?.(msg);
            stopListening();
        }
    }, [isSupported, lang, continuous, interimResults, onFinalTranscript, onError, stopListening]);

    const resetTranscript = useCallback(() => {
        finalAccumulatorRef.current = '';
        setTranscript('');
        setInterimTranscript('');
    }, []);

    // Cleanup on unmount
    useEffect(() => {
        return () => {
            isListeningRef.current = false;
            if (recognitionRef.current) {
                try { recognitionRef.current.stop(); } catch (_) { /* ignore */ }
            }
        };
    }, []);

    return {
        isListening,
        transcript,
        interimTranscript,
        error,
        isSupported,
        startListening,
        stopListening,
        resetTranscript,
    };
}

import { useSearchParams } from 'react-router-dom';
import { useState, useEffect, useRef, useCallback } from 'react';
import { useAuth } from '../hooks/useAuth';
import { useSocket } from '../hooks/useSocket';
import { communityApi } from '../services/api';
import ChannelList from '../components/community/ChannelList';
import ChatWindow from '../components/community/ChatWindow';
import MembersList from '../components/community/MembersList';
import PostsFeed from '../components/community/PostsFeed';
import DirectMessages from '../components/community/DirectMessages';
import {
  MessageSquare,
  Users,
  FileText,
  Mail,
  Menu,
  X,
  Plus,
  Search,
  Hash
} from 'lucide-react';
import toast from 'react-hot-toast';
import { SkeletonListItems, SkeletonPostList } from '../components/ui/Skeleton';
import { motion, AnimatePresence } from 'framer-motion';

export default function Community() {
  const { user } = useAuth();
  const { isConnected, onlineUsers, subscribe, joinChannel, leaveChannel } = useSocket();
  const [searchParams, setSearchParams] = useSearchParams();

  // View state
  const [activeView, setActiveView] = useState(searchParams.get('view') || 'channels'); // channels, posts, dms
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [membersOpen, setMembersOpen] = useState(true);

  // Sync activeView with search parameter changes
  useEffect(() => {
    const view = searchParams.get('view');
    if (view && ['channels', 'posts', 'dms'].includes(view)) {
      setActiveView(view);
    }
  }, [searchParams]);

  // Update URL search parameters when tab is clicked
  const handleTabChange = (view) => {
    setActiveView(view);
    setSearchParams({ view });
  };

  // Channel state
  const [channels, setChannels] = useState([]);
  const [activeChannel, setActiveChannel] = useState(null);
  const [messages, setMessages] = useState([]);
  const [loadingChannels, setLoadingChannels] = useState(true);
  const [loadingMessages, setLoadingMessages] = useState(false);

  // Modal state
  const [showCreateChannel, setShowCreateChannel] = useState(false);

  // Handle optimistic message - immediately show in UI
  const handleOptimisticMessage = useCallback((optimisticMessage) => {
    setMessages(prev => [...prev, optimisticMessage]);
    // Update channel's last message
    setChannels(prev => prev.map(ch => {
      const chId = ch.id || ch._id;
      return chId === optimisticMessage.channelId
        ? { ...ch, lastMessage: { content: optimisticMessage.content, senderName: optimisticMessage.sender.name, timestamp: optimisticMessage.createdAt } }
        : ch;
    }));
  }, []);

  // Handle optimistic reaction - immediately show in UI
  const handleOptimisticReaction = useCallback(({ messageId, emoji, action }) => {
    setMessages(prev => prev.map(msg => {
      const msgId = msg.id || msg._id;
      if (msgId !== messageId) return msg;

      let reactions = [...(msg.reactions || [])];
      const reactionIndex = reactions.findIndex(r => r.emoji === emoji);

      if (action === 'add') {
        if (reactionIndex >= 0) {
          // Add user to existing reaction
          const userAlreadyReacted = reactions[reactionIndex].users.some(u => u.uid === user?.uid);
          if (!userAlreadyReacted) {
            reactions[reactionIndex] = {
              ...reactions[reactionIndex],
              users: [...reactions[reactionIndex].users, { uid: user?.uid, name: user?.name || user?.displayName }]
            };
          }
        } else {
          // Create new reaction
          reactions.push({
            emoji,
            users: [{ uid: user?.uid, name: user?.name || user?.displayName }]
          });
        }
      } else if (action === 'remove') {
        if (reactionIndex >= 0) {
          reactions[reactionIndex] = {
            ...reactions[reactionIndex],
            users: reactions[reactionIndex].users.filter(u => u.uid !== user?.uid)
          };
          if (reactions[reactionIndex].users.length === 0) {
            reactions = reactions.filter(r => r.emoji !== emoji);
          }
        }
      }

      return { ...msg, reactions };
    }));
  }, [user]);

  // Handle optimistic edit - immediately show in UI
  const handleOptimisticEdit = useCallback(({ messageId, content }) => {
    setMessages(prev => prev.map(msg => {
      const msgId = msg.id || msg._id;
      return msgId === messageId
        ? { ...msg, content, isEdited: true, editedAt: new Date().toISOString() }
        : msg;
    }));
  }, []);

  // Handle optimistic delete - immediately show in UI
  const handleOptimisticDelete = useCallback(({ messageId }) => {
    setMessages(prev => prev.map(msg => {
      const msgId = msg.id || msg._id;
      return msgId === messageId ? { ...msg, isDeleted: true } : msg;
    }));
  }, []);

  // Socket event handlers - must be defined before the useEffect that uses them
  const handleNewMessage = useCallback((data) => {
    const channelId = activeChannel?.id || activeChannel?._id;
    if (data.channelId === channelId) {
      // Check if this is a confirmation of our optimistic message
      if (data.tempId) {
        // Replace optimistic message with confirmed one
        setMessages(prev => prev.map(msg =>
          (msg.id === data.tempId || msg._id === data.tempId)
            ? { ...data, isOptimistic: false }
            : msg
        ));
      } else if (data.sender?.uid !== user?.uid) {
        // Only add if it's from another user (we already have our own messages)
        setMessages(prev => [...prev, data]);
      }
    }
    // Update channel's last message
    setChannels(prev => prev.map(ch => {
      const chId = ch.id || ch._id;
      return chId === data.channelId
        ? { ...ch, lastMessage: { content: data.content, senderName: data.sender.name, timestamp: data.createdAt } }
        : ch;
    }));
  }, [activeChannel, user]);

  const handleChannelMessages = useCallback((data) => {
    const channelId = activeChannel?.id || activeChannel?._id;
    if (data.channelId === channelId) {
      setMessages(data.messages);
      setLoadingMessages(false);
    }
  }, [activeChannel]);

  const handleNewChannel = useCallback(({ channel }) => {
    setChannels(prev => [...prev, channel]);
  }, []);

  // Handle message confirmation from server - replace optimistic message with confirmed one
  const handleMessageConfirmed = useCallback((data) => {
    const channelId = activeChannel?.id || activeChannel?._id;
    if (data.channelId === channelId && data.tempId) {
      setMessages(prev => prev.map(msg =>
        (msg.id === data.tempId || msg._id === data.tempId)
          ? { ...data, isOptimistic: false }
          : msg
      ));
    }
  }, [activeChannel]);

  const handleMessageEdited = useCallback(({ messageId, content, editedAt }) => {
    setMessages(prev => prev.map(msg => {
      const msgId = msg.id || msg._id;
      return msgId === messageId ? { ...msg, content, isEdited: true, editedAt } : msg;
    }));
  }, []);

  const handleMessageDeleted = useCallback(({ messageId }) => {
    setMessages(prev => prev.filter(msg => {
      const msgId = msg.id || msg._id;
      return msgId !== messageId;
    }));
  }, []);

  const handleReactionUpdated = useCallback(({ messageId, reactions }) => {
    setMessages(prev => prev.map(msg => {
      const msgId = msg.id || msg._id;
      return msgId === messageId ? { ...msg, reactions } : msg;
    }));
  }, []);

  const fetchChannels = useCallback(async () => {
    try {
      setLoadingChannels(true);
      const data = await communityApi.getChannels();
      setChannels(data.channels);
      // Auto-select first channel
      setActiveChannel(current => current || data.channels[0] || null);
    } catch (error) {
      toast.error('Failed to load channels', { id: 'community-channels-load-error' });
    } finally {
      setLoadingChannels(false);
    }
  }, []);

  // Fetch channels on mount
  useEffect(() => {
    fetchChannels();
  }, [fetchChannels]);

  // Subscribe to socket events
  useEffect(() => {
    const unsubNewMessage = subscribe('new_message', handleNewMessage);
    const unsubChannelMessages = subscribe('channel_messages', handleChannelMessages);
    const unsubNewChannel = subscribe('new_channel', handleNewChannel);
    const unsubMessageConfirmed = subscribe('message_confirmed', handleMessageConfirmed);
    const unsubMessageEdited = subscribe('message_edited', handleMessageEdited);
    const unsubMessageDeleted = subscribe('message_deleted', handleMessageDeleted);
    const unsubReactionUpdated = subscribe('message_reaction_updated', handleReactionUpdated);

    return () => {
      unsubNewMessage();
      unsubChannelMessages();
      unsubNewChannel();
      unsubMessageConfirmed();
      unsubMessageEdited();
      unsubMessageDeleted();
      unsubReactionUpdated();
    };
  }, [subscribe, handleNewMessage, handleChannelMessages, handleNewChannel, handleMessageConfirmed, handleMessageEdited, handleMessageDeleted, handleReactionUpdated]);

  // Join channel when selected
  useEffect(() => {
    if (activeChannel) {
      const channelId = activeChannel.id || activeChannel._id;
      setLoadingMessages(true);
      joinChannel(channelId);
      return () => leaveChannel(channelId);
    }
  }, [activeChannel, joinChannel, leaveChannel]);

  const handleChannelSelect = (channel) => {
    const activeId = activeChannel?.id || activeChannel?._id;
    const newId = channel.id || channel._id;
    if (activeId !== newId) {
      setActiveChannel(channel);
      setMessages([]);
      setLoadingMessages(true);
    }
  };

  const handleCreateChannel = async (channelData) => {
    try {
      const data = await communityApi.createChannel(channelData);
      setChannels(prev => [...prev, data.channel]);
      setActiveChannel(data.channel);
      setShowCreateChannel(false);
      toast.success('Channel created!');
    } catch (error) {
      toast.error(error.message, { id: 'community-create-channel-error' });
    }
  };

  return (
    <div className="h-full bg-background">
      <div className="h-full flex">
        {/* Left Sidebar - Channels/Navigation */}
<div className={`${sidebarOpen ? 'w-72' : 'w-0'} bg-background border-r border-border flex flex-col transition-all duration-300 overflow-hidden shrink-0`}>          {/* View Tabs */}
          <div className="p-3 border-b border-border">
<div className="flex gap-1 bg-muted p-1 rounded-lg w-full">
                <button
                onClick={() => handleTabChange('channels')}
                className={`flex-1 flex items-center justify-center gap-1.5 py-2 px-3 rounded-md text-sm font-medium transition-colors ${activeView === 'channels' ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'
                  }`}
              >
                <MessageSquare className="w-4 h-4" />
                <span className="inline">Chat</span>
              </button>
              <button
                onClick={() => handleTabChange('posts')}
                className={`flex-1 flex items-center justify-center gap-1.5 py-2 px-3 rounded-md text-sm font-medium transition-colors ${activeView === 'posts' ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'
                  }`}
              >
                <FileText className="w-4 h-4" />
                <span className="inline">Posts</span>
              </button>
              <button
                onClick={() => handleTabChange('dms')}
                className={`flex-1 flex items-center justify-center gap-1.5 py-2 px-3 rounded-md text-sm font-medium transition-colors ${activeView === 'dms' ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'
                  }`}
              >
                <Mail className="w-4 h-4" />
                <span className="inline">DMs</span>
              </button>
            </div>
          </div>

          {/* Connection Status */}
          <div className="px-4 py-2 border-b border-border">
            <div className="flex items-center gap-2 text-xs">
              <span className={`w-2 h-2 rounded-full ${isConnected ? 'bg-green-500' : 'bg-red-500'}`}></span>
              <span className="text-muted-foreground">{isConnected ? 'Connected' : 'Disconnected'}</span>
              <span className="text-muted-foreground/50 ml-auto">{onlineUsers.length} online</span>
            </div>
          </div>

          {/* Channel List or DM List */}
          <div className="flex-1 overflow-y-auto">
            {activeView === 'channels' && (
              <ChannelList
                channels={channels}
                activeChannel={activeChannel}
                onSelectChannel={handleChannelSelect}
                onCreateChannel={() => setShowCreateChannel(true)}
                loading={loadingChannels}
              />
            )}
            {activeView === 'dms' && (
              <DirectMessages />
            )}
          </div>
        </div>

        {/* Sidebar Toggle */}
        <button
          onClick={() => setSidebarOpen(!sidebarOpen)}
          className="absolute left-0 top-1/2 -translate-y-1/2 z-10 bg-card border border-border rounded-r-lg p-1.5 shadow-md hover:bg-muted lg:hidden"
        >
          {sidebarOpen ? <X className="w-4 h-4 text-foreground" /> : <Menu className="w-4 h-4 text-foreground" />}
        </button>

        {/* Main Content */}
        <div className="flex-1 flex flex-col min-w-0 bg-background">
          {activeView === 'channels' && activeChannel ? (
            <ChatWindow
              channel={activeChannel}
              messages={messages}
              currentUser={user}
              onOptimisticMessage={handleOptimisticMessage}
              onOptimisticReaction={handleOptimisticReaction}
              onOptimisticEdit={handleOptimisticEdit}
              onOptimisticDelete={handleOptimisticDelete}
              loading={loadingMessages}
            />
          ) : activeView === 'posts' ? (
            <PostsFeed />
          ) : activeView === 'dms' ? (
            <div className="flex-1 flex items-center justify-center text-muted-foreground bg-background min-w-0">
              <div className="text-center px-6">
                <Mail className="w-12 h-12 mx-auto mb-3 text-muted-foreground/30" />
                <p className="text-muted-foreground">Select a conversation to start messaging</p>
              </div>
            </div>
          ) : (
            <div className="flex-1 flex items-center justify-center text-muted-foreground">
              <div className="text-center">
                <MessageSquare className="w-12 h-12 mx-auto mb-3 text-muted-foreground/30" />
                <p className="text-muted-foreground">Select a channel to start chatting</p>
              </div>
            </div>
          )}
        </div>

        {/* Right Sidebar - Members */}
        {activeView === 'channels' && (
          <div className={`${membersOpen ? 'w-60' : 'w-0'} bg-background border-l border-border transition-all duration-300 overflow-hidden hidden lg:block`}>
            <MembersList
              channel={activeChannel}
              onlineUsers={onlineUsers}
            />
          </div>
        )}

        {/* Members Toggle */}
        {activeView === 'channels' && (
          <button
            onClick={() => setMembersOpen(!membersOpen)}
            className="absolute right-0 top-1/2 -translate-y-1/2 z-10 bg-card border border-border rounded-l-lg p-1.5 shadow-md hover:bg-muted hidden lg:block"
          >
            <Users className="w-4 h-4 text-foreground" />
          </button>
        )}

        {/* Create Channel Modal */}
        {showCreateChannel && (
          <CreateChannelModal
            onClose={() => setShowCreateChannel(false)}
            onCreate={handleCreateChannel}
          />
        )}
      </div>
    </div>
  );
}

// Create Channel Modal Component
function CreateChannelModal({ onClose, onCreate }) {
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [category, setCategory] = useState('general');
  const [type, setType] = useState('public');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!name.trim()) return;

    setLoading(true);
    try {
      await onCreate({ name, description, category, type });
    } finally {
      setLoading(false);
    }
  };

  const categories = [
    { value: 'general', label: '💬 General' },
    { value: 'job-hunting', label: '🔍 Job Hunting' },
    { value: 'interview-prep', label: '🎯 Interview Prep' },
    { value: 'resume-tips', label: '📄 Resume Tips' },
    { value: 'networking', label: '🤝 Networking' },
    { value: 'other', label: '📌 Other' }
  ];

  return (
    <div className="fixed inset-0 bg-background/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-card border border-border rounded-xl shadow-xl max-w-md w-full p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-semibold text-foreground flex items-center gap-2">
            <Hash className="w-5 h-5 text-primary" />
            Create Channel
          </h2>
          <button onClick={onClose} className="text-muted-foreground hover:text-foreground transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-muted-foreground mb-1">
              Channel Name
            </label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g., frontend-devs"
              className="w-full px-3 py-2 bg-muted border border-border rounded-lg text-foreground placeholder:text-muted-foreground focus:ring-2 focus:ring-primary focus:border-transparent"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-muted-foreground mb-1">
              Description
            </label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="What's this channel about?"
              rows={2}
              className="w-full px-3 py-2 bg-muted border border-border rounded-lg text-foreground placeholder:text-muted-foreground focus:ring-2 focus:ring-primary focus:border-transparent"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-muted-foreground mb-1">
              Category
            </label>
            <select
              value={category}
              onChange={(e) => setCategory(e.target.value)}
              className="w-full px-3 py-2 bg-muted border border-border rounded-lg text-foreground focus:ring-2 focus:ring-primary focus:border-transparent"
            >
              {categories.map(cat => (
                <option key={cat.value} value={cat.value}>{cat.label}</option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-muted-foreground mb-2">
              Visibility
            </label>
            <div className="flex gap-4">
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="radio"
                  name="type"
                  value="public"
                  checked={type === 'public'}
                  onChange={(e) => setType(e.target.value)}
                  className="text-primary"
                />
                <span className="text-sm text-foreground">Public</span>
              </label>
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="radio"
                  name="type"
                  value="private"
                  checked={type === 'private'}
                  onChange={(e) => setType(e.target.value)}
                  className="text-primary"
                />
                <span className="text-sm text-foreground">Private</span>
              </label>
            </div>
          </div>

          <div className="flex gap-3 pt-2">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-4 py-2 border border-border rounded-lg text-foreground hover:bg-muted transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={loading || !name.trim()}
              className="flex-1 px-4 py-2 bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 font-medium disabled:opacity-50 transition-colors"
            >
              {loading ? 'Creating...' : 'Create Channel'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

