                        Clear
                      </button>
                    )}
                  </div>

                  {!jdSummary && (
                    <>
                      <div className="flex items-center gap-2 mb-3 text-xs">
                        {['none', 'paste', 'url'].map((m) => (
                          <button
                            key={m}
