                  <h2 className="text-xl font-bold text-foreground mb-5 flex items-center gap-2">
                    <Sparkles className="w-5 h-5 text-blue-400" /> Optimized Headline Suggestions
                  </h2>
                  <div className="space-y-3">
                    {results.headlineSuggestions.map((h, i) => (
                      <HeadlineCard key={i} headline={h} index={i} copied={copiedIndex} onCopy={copyToClipboard} />
                    ))}
                  </div>
                </div>
              )}

              {/* About Section Rewrite */}
              {results.aboutRewrite && (
                <div className="bg-card/60 backdrop-blur-sm border border-border rounded-2xl p-6">
                  <div className="flex items-center justify-between mb-4">
                    <h2 className="text-xl font-bold text-foreground flex items-center gap-2">
                      <Linkedin className="w-5 h-5 text-blue-400" /> Rewritten About Section
                    </h2>
                    <div className="flex gap-2">
                      <button
                        onClick={copyAbout}
                        className="flex items-center gap-1.5 text-sm px-3 py-1.5 rounded-lg bg-primary/10 text-primary hover:bg-primary/20 border border-primary/20 transition font-medium"
                      >
                        {aboutCopied ? <><Check className="w-3.5 h-3.5" /> Copied</> : <><Copy className="w-3.5 h-3.5" /> Copy All</>}
                      </button>
                      <button
                        onClick={() => setAboutExpanded(!aboutExpanded)}
                        className="flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground transition"
                      >
                        {aboutExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                      </button>
                    </div>
                  </div>
                  <div className={`text-sm text-muted-foreground leading-relaxed whitespace-pre-wrap bg-muted/30 rounded-xl p-4 border border-border ${!aboutExpanded ? 'line-clamp-5' : ''}`}>
                    {results.aboutRewrite}
                  </div>
                  {!aboutExpanded && (
                    <button onClick={() => setAboutExpanded(true)} className="text-xs text-primary hover:text-primary/80 mt-2 font-medium">
                      Show full rewrite →
                    </button>
                  )}
                </div>
              )}

              {/* Quick Wins + Skills Gap */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Quick Wins */}
                {results.quickWins?.length > 0 && (
                  <div className="bg-card/60 backdrop-blur-sm border border-border rounded-2xl p-6">
                    <h2 className="text-lg font-bold text-foreground mb-4 flex items-center gap-2">
                      <Zap className="w-5 h-5 text-yellow-400" /> Quick Wins
                    </h2>
                    <div className="space-y-3">
                      {results.quickWins.map((win, i) => {
                        const cfg = IMPACT_CONFIG[win.impact] || IMPACT_CONFIG.Low
                        return (
                          <motion.div
                            key={i}
                            initial={{ opacity: 0, x: -10 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ delay: i * 0.07 }}
                            className={`flex items-start gap-3 p-3 rounded-xl border ${cfg.border} ${cfg.bg}`}
                          >
                            <span className={`text-xs font-bold px-2 py-0.5 rounded-full border ${cfg.border} ${cfg.color} ${cfg.bg} shrink-0 mt-0.5`}>
                              {win.impact}
                            </span>
                            <p className="text-sm text-foreground">{win.action}</p>
                          </motion.div>
                        )
                      })}
                    </div>
                  </div>
                )}

                {/* Skills Gap vs Peers */}
                {results.skillsGapVsPeers?.length > 0 && (
                  <div className="bg-card/60 backdrop-blur-sm border border-border rounded-2xl p-6">
                    <h2 className="text-lg font-bold text-foreground mb-4 flex items-center gap-2">
                      <Target className="w-5 h-5 text-red-400" /> Skills Gap vs Industry Peers
                    </h2>
                    <div className="space-y-3">
                      {results.skillsGapVsPeers.map((item, i) => (
                        <motion.div
                          key={i}
                          initial={{ opacity: 0, x: 10 }}
                          animate={{ opacity: 1, x: 0 }}
                          transition={{ delay: i * 0.07 }}
                          onClick={() => copyKeywordToClipboard(item.skill)}
                          className="relative flex items-start gap-3 p-3 rounded-xl bg-muted/40 border border-border cursor-pointer transition hover:bg-muted/60 hover:border-primary/40"
                        >
                          <span className="w-2 h-2 rounded-full bg-red-400 shrink-0 mt-1.5" />
                          <div>
                            <p className="text-sm font-semibold text-foreground">{item.skill}</p>
                            <p className="text-xs text-muted-foreground mt-0.5">{item.reason}</p>
                          </div>
                          {copiedSkill === item.skill && (
                            <span className="pointer-events-none absolute -top-7 right-3 rounded-full bg-green-500/95 px-2 py-1 text-[10px] font-semibold text-white shadow-lg">
                              Copied!
                            </span>
                          )}
                        </motion.div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  )
}

import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { useAuth } from '../hooks/useAuth';
import { CanvasRevealEffect } from '../components/ui/sign-in-flow-1';
import toast from 'react-hot-toast';

export default function Login() {
  const { login, loginWithGoogle, loginWithGitHub, loginWithLinkedIn } = useAuth();
  const navigate = useNavigate();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [socialLoading, setSocialLoading] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!email || !password) {
      toast.error('Please fill in all fields');
      return;
    }
    setLoading(true);
    try {
      await login(email, password);
      toast.success('Welcome back!');
      navigate('/dashboard', { replace: true });
    } catch (err) {
      const code = err?.code || '';
      if (code === 'auth/user-not-found' || code === 'auth/wrong-password' || code === 'auth/invalid-credential') {
        toast.error('Invalid email or password');
      } else if (code === 'auth/too-many-requests') {
        toast.error('Too many attempts. Please try again later.');
      } else {
        toast.error(err.message || 'Login failed. Please try again.');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleSocialLogin = async (provider, providerName) => {
    setSocialLoading(providerName);
    try {
      if (providerName === 'LinkedIn') {
        provider(); // LinkedIn redirects, no await
        return;
      }
      await provider();
      toast.success('Welcome back!');
      navigate('/dashboard', { replace: true });
    } catch (err) {
      if (err?.code !== 'auth/popup-closed-by-user') {
        toast.error(`${providerName} sign-in failed. Please try again.`);
      }
    } finally {
      setSocialLoading('');
    }
  };

  const isDisabled = loading || !!socialLoading;

  return (
    <div className="flex w-full flex-col min-h-screen bg-black relative overflow-hidden">
      {/* Animated background */}
      <div className="absolute inset-0 z-0">
        <div className="absolute inset-0">
          <CanvasRevealEffect
            animationSpeed={2.5}
            containerClassName="bg-black"
            colors={[[255, 255, 255], [255, 255, 255]]}
            dotSize={5}
            reverse={false}
          />
        </div>
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_rgba(0,0,0,0.92)_0%,_rgba(0,0,0,0.7)_50%,_transparent_100%)]" />
        <div className="absolute top-0 left-0 right-0 h-1/3 bg-gradient-to-b from-black to-transparent" />
        <div className="absolute bottom-0 left-0 right-0 h-1/4 bg-gradient-to-t from-black to-transparent" />
      </div>

      {/* Content */}
      <div className="relative z-10 flex flex-1 flex-col items-center justify-center px-4 py-12">
        {/* Logo / Brand */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="mb-8 text-center"
        >
          <Link to="/" className="inline-flex items-center gap-2 group">
            <div className="relative w-8 h-8 flex items-center justify-center">
              <span className="absolute w-2 h-2 rounded-full bg-white top-0 left-1/2 transform -translate-x-1/2 opacity-80 group-hover:opacity-100 transition-opacity" />
              <span className="absolute w-2 h-2 rounded-full bg-white left-0 top-1/2 transform -translate-y-1/2 opacity-80 group-hover:opacity-100 transition-opacity" />
              <span className="absolute w-2 h-2 rounded-full bg-white right-0 top-1/2 transform -translate-y-1/2 opacity-80 group-hover:opacity-100 transition-opacity" />
              <span className="absolute w-2 h-2 rounded-full bg-white bottom-0 left-1/2 transform -translate-x-1/2 opacity-80 group-hover:opacity-100 transition-opacity" />
            </div>
            <span className="text-white text-lg font-semibold tracking-tight">TeacHforPLaCeMeNt</span>
          </Link>
        </motion.div>

        {/* Card */}
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.15 }}
          className="w-full max-w-[420px]"
        >
          <div className="backdrop-blur-xl bg-white/[0.04] border border-white/[0.08] rounded-2xl p-8 shadow-2xl">
            {/* Header */}
            <div className="text-center mb-8">
              <h1 className="text-3xl font-bold text-white tracking-tight">Welcome back</h1>
              <p className="text-white/50 mt-2 text-sm">Sign in to continue your career journey</p>
            </div>

            {/* Social Login Buttons */}
            <div className="space-y-3 mb-6">
              <button
                type="button"
                onClick={() => handleSocialLogin(loginWithGoogle, 'Google')}
                disabled={isDisabled}
                className="w-full flex items-center justify-center gap-3 bg-white/[0.06] hover:bg-white/[0.12] disabled:opacity-40 disabled:cursor-not-allowed text-white border border-white/[0.08] rounded-xl py-3 px-4 transition-all duration-200 text-sm font-medium"
              >
                {socialLoading === 'Google' ? (
                  <Spinner />
                ) : (
                  <GoogleIcon />
                )}
                Continue with Google
              </button>

              <div className="flex gap-3">
                <button
                  type="button"
                  onClick={() => handleSocialLogin(loginWithGitHub, 'GitHub')}
                  disabled={isDisabled}
                  className="flex-1 flex items-center justify-center gap-2 bg-white/[0.06] hover:bg-white/[0.12] disabled:opacity-40 disabled:cursor-not-allowed text-white border border-white/[0.08] rounded-xl py-3 px-4 transition-all duration-200 text-sm font-medium"
                >
                  {socialLoading === 'GitHub' ? (
                    <Spinner />
                  ) : (
                    <GitHubIcon />
                  )}
                  GitHub
                </button>

                <button
                  type="button"
                  onClick={() => handleSocialLogin(loginWithLinkedIn, 'LinkedIn')}
                  disabled={isDisabled}
                  className="flex-1 flex items-center justify-center gap-2 bg-white/[0.06] hover:bg-white/[0.12] disabled:opacity-40 disabled:cursor-not-allowed text-white border border-white/[0.08] rounded-xl py-3 px-4 transition-all duration-200 text-sm font-medium"
                >
                  {socialLoading === 'LinkedIn' ? (
                    <Spinner />
                  ) : (
                    <LinkedInIcon />
                  )}
