          transition={{ duration: 0.4 }}
          className="space-y-6"
        >
          <div className="space-y-2 mb-8">
            <div className="h-9 bg-muted rounded-lg w-1/3 animate-pulse" />
            <div className="h-4 bg-muted rounded-lg w-2/3 animate-pulse" />
          </div>
          <div className="p-6 rounded-2xl bg-card border border-border space-y-6">
            <div className="h-5 bg-muted rounded-lg w-1/4 animate-pulse" />
            <SkeletonList count={3} />
          </div>
        </motion.div>
      </div>
    </div>
  )

  return (
    <div className="min-h-screen bg-background">
      <div className="max-w-4xl mx-auto px-4 py-8">
        <motion.div initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }}>
          <h1 className="text-3xl font-bold text-foreground mb-1">Settings</h1>
          <p className="text-muted-foreground mb-8">Manage notifications and AI provider configuration</p>

          {/* Tab Navigation */}
          <div className="flex gap-1 p-1 rounded-xl bg-muted/50 border border-border mb-8 w-fit">
            {tabs.map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center gap-2 px-5 py-2.5 rounded-lg text-sm font-semibold transition-all duration-200 ${
                  activeTab === tab.id
                    ? 'bg-card text-foreground shadow-sm border border-border'
                    : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                <tab.icon className="w-4 h-4" />
                {tab.label}
              </button>
            ))}
          </div>

          <AnimatePresence mode="wait">
            {/* NOTIFICATIONS TAB */}
            {activeTab === 'notifications' && (
              <motion.div
                key="notifications"
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                transition={{ duration: 0.25 }}
              >
                <div className="relative overflow-hidden p-6 rounded-2xl bg-card/80 backdrop-blur-sm border border-border shadow-[0_8px_30px_rgb(0,0,0,0.06)] hover:shadow-xl hover:border-primary/20 transition-all duration-300 space-y-6">
                  <h2 className="text-lg font-semibold text-foreground flex items-center gap-2">
                    <Bell className="w-5 h-5 text-indigo-400" />
                    Email Notifications
                  </h2>

                  {/* Job Alerts */}
                  <div className="flex items-center justify-between py-4 border-b border-border">
                    <div className="flex items-center gap-3">
                      <Mail className="w-5 h-5 text-indigo-400" />
                      <div>
                        <p className="text-foreground font-medium">Job Alerts</p>
                        <p className="text-muted-foreground text-sm">Get notified when new jobs match your alerts</p>
                      </div>
                    </div>
                    <Toggle
                      value={preferences.jobAlerts}
                      onChange={(val) => setPreferences({ ...preferences, jobAlerts: val })}
                    />
                  </div>

                  {/* Direct Messages */}
                  <div className="flex items-center justify-between py-4 border-b border-border">
                    <div className="flex items-center gap-3">
                      <MessageSquare className="w-5 h-5 text-purple-400" />
                      <div>
                        <p className="text-foreground font-medium">Direct Messages</p>
                        <p className="text-muted-foreground text-sm">Get notified when you receive a DM</p>
                      </div>
                    </div>
                    <Toggle
                      value={preferences.directMessages}
                      onChange={(val) => setPreferences({ ...preferences, directMessages: val })}
                    />
                  </div>

                  {/* Proposal Updates */}
                  <div className="flex items-center justify-between py-4">
                    <div className="flex items-center gap-3">
                      <FileText className="w-5 h-5 text-green-400" />
                      <div>
                        <p className="text-foreground font-medium">Proposal Updates</p>
                        <p className="text-muted-foreground text-sm">Get notified on fellowship proposal changes</p>
                      </div>
                    </div>
                    <Toggle
                      value={preferences.proposalUpdates}
                      onChange={(val) => setPreferences({ ...preferences, proposalUpdates: val })}
                    />
                  </div>

                  <Button
                    onClick={handleSave}
                    loading={saving}
                    variant="gradient"
                    className="w-full flex items-center justify-center gap-2"
                  >
                    <Save className="w-4 h-4" />
                    Save Preferences
                  </Button>
                </div>
              </motion.div>
            )}

            {/* AI PROVIDERS TAB */}
            {activeTab === 'ai-providers' && (
              <motion.div
                key="ai-providers"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                transition={{ duration: 0.25 }}
              >
                <AIProviderSetup />
              </motion.div>
            )}

            {/* INTEGRATIONS TAB — GitHub, etc. */}
            {activeTab === 'integrations' && (
              <motion.div
                key="integrations"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                transition={{ duration: 0.25 }}
                className="space-y-4"
              >
                <div className="mb-2">
                  <h2 className="text-lg font-semibold text-foreground flex items-center gap-2">
                    <Github className="w-5 h-5" />
                    GitHub Integration
                  </h2>
                  <p className="text-sm text-muted-foreground">
                    Connect GitHub to power the GitHub-Powered Portfolio Builder
                    and unlock private repos + 5,000 req/hr.
                  </p>
                </div>
                <GithubTokenCard />
              </motion.div>
            )}
          </AnimatePresence>
        </motion.div>
      </div>
    </div>
  )
}

import React, { useState, useEffect } from 'react';
import { Target, Sparkles, CheckCircle, XCircle, TrendingUp, FileText } from 'lucide-react';
import { motion } from 'framer-motion';
import { enhanceApi, resumeApi } from '../services/api';
import toast from 'react-hot-toast';
import CopyButton from '../components/CopyButton';
import {
  extractSkillsFromText,
  inferCareerFocus,
  getSkillSynergyInsights
} from '../utils/skillSynergy';
// Utility helpers for Skill Synergy Insights.
// These functions detect resume skills, infer the job-related career focus,
// and return complementary skill recommendations.

const SkillGap = () => {
  const [resumes, setResumes] = useState([]);
  const [selectedResumeId, setSelectedResumeId] = useState('');
  const [jobDescription, setJobDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingResumes, setLoadingResumes] = useState(true);
  const [results, setResults] = useState(null);
  const [careerFocus, setCareerFocus] = useState('General Career Growth');
  const [synergyInsights, setSynergyInsights] = useState([]);
  const [detectedSkills, setDetectedSkills] = useState([]);
  // detectedSkills is the inferred set of skills from the resume text
  // careerFocus is the role/category inferred from the job description.

  useEffect(() => {
    const fetchResumes = async () => {
      try {
        const response = await resumeApi.getAll();
        const list = response.data || response.resumes || [];
        setResumes(list);
        if (list.length > 0) setSelectedResumeId(list[0]._id);
      } catch (error) {
        toast.error('Failed to load resumes');
      } finally {
        setLoadingResumes(false);
      }
    };
    fetchResumes();
  }, []);

  const handleAnalyze = async (e) => {
    e.preventDefault();

    if (!selectedResumeId) {
      toast.error('Please select a resume');
      return;
    }
    if (!jobDescription.trim()) {
      toast.error('Please paste a job description');
      return;
    }

    setLoading(true);
    setResults(null);

    try {
      const resumeResponse = await resumeApi.getById(selectedResumeId);
      const resume = resumeResponse.data || resumeResponse;
      const resumeText = resume.originalText || resume.enhancedText || '';

      if (!resumeText) {
        toast.error('Selected resume has no text content');
        setLoading(false);
        return;
      }

      const response = await enhanceApi.analyzeSkillGap(resumeText, jobDescription);
      setResults(response.data);

      // Build the Skill Synergy Insights using resume skills and job focus.
      const parsedSkills = extractSkillsFromText(resumeText);
      setDetectedSkills(parsedSkills);
      const inferredCareerFocus = inferCareerFocus(jobDescription);
      setCareerFocus(inferredCareerFocus);
      setSynergyInsights(getSkillSynergyInsights(parsedSkills, inferredCareerFocus));
    } catch (error) {
      console.error('Skill gap analysis error:', error);
      toast.error(error.message || 'Failed to analyze skill gap. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const getScoreColor = (score) => {
    if (score >= 80) return 'text-green-500';
    if (score >= 60) return 'text-yellow-500';
    if (score >= 40) return 'text-orange-500';
    return 'text-red-500';
  };

  const getScoreBg = (score) => {
    if (score >= 80) return 'bg-green-500/10 border-green-500/20';
    if (score >= 60) return 'bg-yellow-500/10 border-yellow-500/20';
    if (score >= 40) return 'bg-orange-500/10 border-orange-500/20';
    return 'bg-red-500/10 border-red-500/20';
  };

  return (
    <div className="min-h-screen bg-background">
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-1/4 left-0 w-96 h-96 bg-primary/10 rounded-full blur-3xl" />
        <div className="absolute bottom-1/4 right-0 w-96 h-96 bg-indigo-500/10 rounded-full blur-3xl" />
      </div>

      <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center mb-10"
        >
          <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-primary/10 border border-primary/20 text-primary text-sm mb-4">
            <Sparkles className="w-4 h-4" />
            AI-Powered Skill Gap Analyzer
          </div>
          <h1 className="text-4xl md:text-5xl font-bold text-foreground mb-3">
            Skill Gap Analyzer
          </h1>
          <p className="text-lg text-muted-foreground max-w-2xl mx-auto">
            Compare your resume against any job description to identify matching skills, gaps, and get personalized learning suggestions.
          </p>
        </motion.div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Input Section */}
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.1 }}
          >
            <form onSubmit={handleAnalyze} className="space-y-6">
              {/* Resume Selector */}
              <div className="bg-card border border-border rounded-xl p-6">
                <label className="flex items-center gap-2 text-sm font-medium text-foreground mb-3">
                  <FileText className="w-4 h-4 text-primary" />
                  Select Resume
                </label>
                {loadingResumes ? (
                  <div className="h-10 bg-muted animate-pulse rounded-lg" />
                ) : resumes.length === 0 ? (
                  <p className="text-sm text-muted-foreground">
                    No resumes found. Please upload a resume first.
                  </p>
                ) : (
                  <select
                    value={selectedResumeId}
                    onChange={(e) => setSelectedResumeId(e.target.value)}
                    className="w-full px-4 py-2.5 bg-background border border-border rounded-lg text-foreground focus:outline-none focus:ring-2 focus:ring-primary/50"
                  >
                    {resumes.map((resume) => (
                      <option key={resume._id} value={resume._id}>
                        {resume.title || resume.jobRole || 'Untitled Resume'} — {new Date(resume.createdAt).toLocaleDateString()}
                      </option>
                    ))}
                  </select>
                )}
              </div>

              {/* Job Description Input */}
              <div className="bg-card border border-border rounded-xl p-6">
                <label className="flex items-center gap-2 text-sm font-medium text-foreground mb-3">
                  <Target className="w-4 h-4 text-primary" />
                  Job Description
                </label>
                <textarea
                  value={jobDescription}
                  onChange={(e) => setJobDescription(e.target.value)}
                  placeholder="Paste the full job description here..."
                  rows={12}
                  className="w-full px-4 py-3 bg-background border border-border rounded-lg text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/50 resize-none"
                />
              </div>

              <button
                type="submit"
                disabled={loading || !selectedResumeId || !jobDescription.trim()}
                className="w-full py-3 px-6 bg-primary text-primary-foreground rounded-xl font-medium hover:bg-primary/90 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
              >
                {loading ? (
                  <>
                    <div className="w-5 h-5 border-2 border-primary-foreground/30 border-t-primary-foreground rounded-full animate-spin" />
                    Analyzing...
                  </>
                ) : (
                  <>
                    <TrendingUp className="w-5 h-5" />
                    Analyze Skill Gap
                  </>
                )}
              </button>
            </form>
          </motion.div>

          {/* Results Section */}
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.2 }}
            className="space-y-6"
          >
            {!results && !loading && (
              <div className="bg-card border border-border rounded-xl p-12 text-center">
                <Target className="w-16 h-16 text-muted-foreground/30 mx-auto mb-4" />
                <p className="text-muted-foreground">
                  Select a resume and paste a job description to see your skill gap analysis.
                </p>
              </div>
            )}

            {loading && (
              <div className="bg-card border border-border rounded-xl p-8 space-y-4">
                <div className="h-6 bg-muted animate-pulse rounded w-1/3 mx-auto" />
                <div className="h-20 bg-muted animate-pulse rounded" />
                <div className="h-4 bg-muted animate-pulse rounded w-2/3" />
                <div className="h-4 bg-muted animate-pulse rounded w-1/2" />
                <div className="grid grid-cols-2 gap-3 mt-4">
                  {[1,2,3,4].map(i => (
                    <div key={i} className="h-8 bg-muted animate-pulse rounded-full" />
                  ))}
                </div>
              </div>
            )}

            {results && (
              <>
                {/* Match Score */}
                <div className={`border rounded-xl p-6 text-center ${getScoreBg(results.matchScore)}`}>
                  <p className="text-sm font-medium text-muted-foreground mb-1">Match Score</p>
                  <p className={`text-5xl font-bold ${getScoreColor(results.matchScore)}`}>
                    {results.matchScore}%
                  </p>
                  <p className="text-sm text-muted-foreground mt-2">
                    {results.matchScore >= 80 && 'Excellent match! You are well-qualified.'}
                    {results.matchScore >= 60 && results.matchScore < 80 && 'Good match with some areas to improve.'}
                    {results.matchScore >= 40 && results.matchScore < 60 && 'Moderate match. Focus on the missing skills.'}
                    {results.matchScore < 40 && 'Significant gaps. Consider upskilling before applying.'}
                  </p>
                </div>

                {/* Matched Skills */}
                {results.matchedSkills.length > 0 && (
                  <div className="bg-card border border-border rounded-xl p-6">
                    <h3 className="flex items-center gap-2 text-sm font-medium text-foreground mb-4">
                      <CheckCircle className="w-4 h-4 text-green-500" />
                      Matched Skills ({results.matchedSkills.length})
                    </h3>
                    <div className="flex flex-wrap gap-2">
                      {results.matchedSkills.map((skill, idx) => (
                        <span
                          key={idx}
                          className="px-3 py-1.5 text-sm bg-green-500/10 text-green-600 dark:text-green-400 border border-green-500/20 rounded-full"
                        >
                          {skill}
                        </span>
                      ))}
                    </div>
                  </div>
                )}

                {detectedSkills.length > 0 && (
                  <div className="bg-card border border-border rounded-xl p-6">
                    <h3 className="text-sm font-medium text-foreground mb-3">
                      Detected Profile Skills
                    </h3>
                    <div className="flex flex-wrap gap-2">
                      {detectedSkills.map((skill, idx) => (
                        <span
                          key={idx}
                          className="px-3 py-1.5 text-sm bg-slate-500/10 text-slate-300 border border-slate-500/20 rounded-full"
                        >
                          {skill}
                        </span>
                      ))}
                    </div>
                  </div>
                )}

                {/* Missing Skills */}
                {results.missingSkills.length > 0 && (
                  <div className="bg-card border border-border rounded-xl p-6">
                    <h3 className="flex items-center gap-2 text-sm font-medium text-foreground mb-4">
                      <XCircle className="w-4 h-4 text-red-500" />
                      Missing Skills ({results.missingSkills.length})
                    </h3>
                    <div className="flex flex-wrap gap-2">
                      {results.missingSkills.map((skill, idx) => (
                        <span
                          key={idx}
                          className="px-3 py-1.5 text-sm bg-red-500/10 text-red-600 dark:text-red-400 border border-red-500/20 rounded-full"
                        >
                          {skill}
                        </span>
                      ))}
                    </div>
                  </div>
                )}

                {synergyInsights.length > 0 ? (
                  <div className="bg-card border border-border rounded-xl p-6">
                    <div className="flex items-center justify-between gap-2 mb-4">
                      <div>
                        <h3 className="text-sm font-medium text-foreground">
                          Skill Synergy Insights
                        </h3>
                        <p className="text-sm text-muted-foreground mt-1">
                          Complementary skills recommended for your current profile and career focus.
                        </p>
                        <p className="text-sm text-muted-foreground mt-1">
                          Primary focus: <span className="font-medium text-foreground">{careerFocus}</span>
                        </p>
                      </div>
                      <CopyButton
                        text={synergyInsights.map((item) => `${item.skill}: ${item.description}`).join('\n')}
                        label="Copy"
                        size={14}
                      />
                    </div>
                    <div className="grid gap-4">
                      {synergyInsights.map((item, index) => (
                        <div
                          key={index}
                          className="rounded-2xl border border-border p-4 bg-background/70"
                        >
                          <div className="flex items-center justify-between gap-4">
                            <p className="font-semibold text-foreground">{item.skill}</p>
                            <span className="text-[11px] uppercase tracking-[0.24em] text-muted-foreground">
                              {item.source}
                            </span>
                          </div>
                          <p className="mt-2 text-sm text-muted-foreground">
                            {item.description}
                          </p>
                        </div>
                      ))}
                    </div>
                  </div>
                ) : (
                  <div className="bg-card border border-border rounded-xl p-6">
                    <h3 className="text-sm font-medium text-foreground mb-3">
                      Skill Synergy Insights
                    </h3>
                    <p className="text-sm text-muted-foreground">
                      No tailored synergy recommendations were detected from your resume skills. Try adding more explicit skills like Python, SQL, or Data Analysis to get better insights.
                    </p>
                  </div>
                )}

                {/* Suggestions */}
                {results.suggestions && (
                  <div className="bg-card border border-border rounded-xl p-6">
                    <div className="flex items-center justify-between gap-2 mb-4">
                      <h3 className="flex items-center gap-2 text-sm font-medium text-foreground">
                        <Sparkles className="w-4 h-4 text-primary" />
                        Learning Suggestions
                      </h3>
                      <CopyButton text={results.suggestions} label="Copy" size={14} />
                    </div>
                    <p className="text-sm text-muted-foreground leading-relaxed whitespace-pre-line">
                      {results.suggestions}
                    </p>
                  </div>
                )}
              </>
            )}
          </motion.div>
        </div>
      </div>
    </div>
  );
};

export default SkillGap;

