              </div>
              <div>
                <h2 className="text-lg font-semibold text-foreground">Import from LinkedIn</h2>
                <p className="text-sm text-muted-foreground">Paste your public LinkedIn profile URL to auto-fill your resume</p>
              </div>
            </div>

            <div className="flex gap-3">
              <input
                type="text"
                value={linkedinUrl}
                onChange={(e) => {
                  setLinkedinUrl(e.target.value)
                  setLinkedinPreview(null)
                  setLinkedinProfile(null)
                }}
                placeholder="https://linkedin.com/in/your-profile"
                className="flex-1 px-4 py-2.5 rounded-lg bg-muted/50 border border-border text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary transition-all duration-200 text-sm"
              />
              <Button
                variant="secondary"
                onClick={handleLinkedinPreview}
                loading={linkedinLoading}
                disabled={!linkedinUrl.trim() || linkedinLoading}
              >
                Preview
              </Button>
            </div>

            {/* Preview card */}
            {linkedinPreview && (
              <motion.div
                initial={{ opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                className="mt-5 rounded-xl border border-sky-500/20 bg-sky-500/5 p-5"
              >
                <div className="flex items-start gap-4 mb-4">
                  <div className="w-12 h-12 rounded-full bg-gradient-to-br from-primary to-secondary flex items-center justify-center shrink-0">
                    <span className="text-primary-foreground font-bold text-lg">
                      {linkedinPreview.name?.charAt(0)?.toUpperCase() || '?'}
                    </span>
                  </div>
                  <div className="flex-1 min-w-0">
                    <h3 className="text-foreground font-semibold text-base">{linkedinPreview.name}</h3>
                    {linkedinPreview.headline && (
                      <p className="text-sky-600 dark:text-sky-400 text-sm mt-0.5">{linkedinPreview.headline}</p>
                    )}
                    {linkedinPreview.location && (
                      <p className="text-muted-foreground text-xs mt-0.5">{linkedinPreview.location}</p>
                    )}
                  </div>
                </div>

                <div className="flex flex-wrap gap-4 text-sm text-muted-foreground mb-4">
                  {linkedinPreview.experienceCount > 0 && (
                    <span className="flex items-center gap-1.5">
                      <Briefcase className="w-4 h-4 text-muted-foreground" />
                      {linkedinPreview.experienceCount} experience {linkedinPreview.experienceCount === 1 ? 'entry' : 'entries'}
                    </span>
                  )}
                  {linkedinPreview.educationCount > 0 && (
                    <span className="flex items-center gap-1.5">
                      <GraduationCap className="w-4 h-4 text-muted-foreground" />
                      {linkedinPreview.educationCount} education {linkedinPreview.educationCount === 1 ? 'entry' : 'entries'}
                    </span>
                  )}
                  {linkedinPreview.skills?.length > 0 && (
                    <span className="flex items-center gap-1.5">
                      <User className="w-4 h-4 text-muted-foreground" />
                      {linkedinPreview.skills.length} skills
                    </span>
                  )}
                </div>

                {linkedinPreview.skills?.length > 0 && (
                  <div className="flex flex-wrap gap-1.5 mb-5">
                    {linkedinPreview.skills.slice(0, 8).map((skill, i) => (
                      <span
                        key={i}
                        className="px-2.5 py-1 bg-sky-500/10 border border-sky-500/20 text-sky-600 dark:text-sky-400 rounded-full text-xs font-medium"
                      >
                        {skill}
                      </span>
                    ))}
                    {linkedinPreview.skills.length > 8 && (
                      <span className="px-2.5 py-1 text-muted-foreground text-xs">
                        +{linkedinPreview.skills.length - 8} more
                      </span>
                    )}
                  </div>
                )}

                <Button
                  variant="gradient"
                  onClick={handleLinkedinImport}
                  loading={importing}
                  className="w-full"
                >
                  <ArrowRight className="w-4 h-4 mr-1.5" />
                  Import & Enhance with AI
                </Button>
              </motion.div>
            )}
          </motion.div>
        )}

        {/* How it works */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
          className="mt-12"
        >
          <h3 className="text-lg font-semibold text-foreground mb-6 text-center">How It Works</h3>
          <div className="grid md:grid-cols-3 gap-6">
            <div className="text-center">
              <div className="w-10 h-10 bg-primary rounded-full flex items-center justify-center mx-auto mb-3 text-foreground font-bold">1</div>
              <h4 className="text-foreground font-medium mb-1">Upload Resume</h4>
              <p className="text-muted-foreground text-sm">Upload your PDF resume file</p>
            </div>
            <div className="text-center">
              <div className="w-10 h-10 bg-primary rounded-full flex items-center justify-center mx-auto mb-3 text-foreground font-bold">2</div>
              <h4 className="text-foreground font-medium mb-1">Get ATS Score</h4>
              <p className="text-muted-foreground text-sm">See how your resume scores for your target job</p>
            </div>
            <div className="text-center">
              <div className="w-10 h-10 bg-primary rounded-full flex items-center justify-center mx-auto mb-3 text-foreground font-bold">3</div>
              <h4 className="text-foreground font-medium mb-1">Improve with AI</h4>
              <p className="text-muted-foreground text-sm">One-click AI enhancement based on analysis</p>
            </div>
          </div>
        </motion.div>
      </div>
    </div>
  )
}

import { useState, useEffect, useRef } from 'react'
import { useParams, Link } from 'react-router-dom'
import toast from 'react-hot-toast'
import { motion } from 'framer-motion'
import {
  MapPin, Globe, Github, Linkedin, Pencil, Save, X,
  FileText, Mic, Heart, MessageSquare, Calendar,
  Plus, ExternalLink, Camera, Loader2, Briefcase,
  GraduationCap, Phone, Cake, Star
} from 'lucide-react'
import { useAuth } from '../hooks/useAuth'
import { userProfileApi } from '../services/api'
import Button from '../components/Button'
import Input from '../components/Input'
import { SkeletonProfile } from '../components/ui/Skeleton'
import AnalysisSkeleton from '../components/github/AnalysisSkeleton'
import { SkeletonList } from '../components/ui/Skeleton'
import { getGithubUsername } from '../utils/github'
import { uploadAvatar } from '../utils/avatarUpload'

const AVATAR_GRADIENTS = [
  'from-indigo-500 to-purple-600',
  'from-sky-500 to-indigo-600',
  'from-emerald-500 to-teal-600',
  'from-amber-500 to-orange-600',
  'from-rose-500 to-pink-600',
]

const itemVariants = {
  hidden: { opacity: 0, y: 16 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.4 } },
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { staggerChildren: 0.08 } },
}

export default function UserProfile() {
  const { uid: paramUid } = useParams()
  const { user } = useAuth()

  const targetUid = paramUid || user?.uid
  const isOwnProfile = !paramUid || paramUid === user?.uid

  const [profile, setProfile] = useState(null)
  const [stats, setStats] = useState({ resumesCreated: 0, interviewsDone: 0 })
  const [activity, setActivity] = useState([])
  const [loading, setLoading] = useState(true)
  const [editing, setEditing] = useState(false)
  const [saving, setSaving] = useState(false)
  // When true the GitHub repository analysis skeleton will show
  const [isRepoAnalyzing, setIsRepoAnalyzing] = useState(false)
  // Avatar upload state
  const [avatarUploading, setAvatarUploading] = useState(false)
  const [avatarProgress, setAvatarProgress] = useState(0)
  const avatarInputRef = useRef(null)
  const [form, setForm] = useState({
    displayName: '',
    bio: '',
    jobRole: '',
    skills: '',
    location: '',
    website: '',
    github: '',
    linkedin: '',
    // New personal-info fields
    phone: '',
    headline: '',
    dateOfBirth: '',
    gender: '',
    company: '',
    yearsOfExperience: '',
    collegeStudent: false,
    openToWork: false,
    languages: '',
    resumeHeadline: '',
  })

  useEffect(() => {
    if (targetUid) fetchAll()
  }, [targetUid])

  const fetchAll = async () => {
    setLoading(true)
    try {
      const [profileResult, statsResult, activityResult] = await Promise.allSettled([
        isOwnProfile ? userProfileApi.getMyProfile() : userProfileApi.getProfile(targetUid),
        isOwnProfile ? userProfileApi.getMyStats() : userProfileApi.getStats(targetUid),
        isOwnProfile ? userProfileApi.getMyActivity() : userProfileApi.getActivity(targetUid),
      ])

      if (profileResult.status === 'rejected') {
        throw profileResult.reason
      }

      const profileRes = profileResult.value
      const statsRes = statsResult.status === 'fulfilled' ? statsResult.value : { stats: { resumesCreated: 0, interviewsDone: 0 } }
      const activityRes = activityResult.status === 'fulfilled' ? activityResult.value : { activity: [] }

      setProfile(profileRes.profile)
      setStats(statsRes.stats)
      setActivity(activityRes.activity)

      if (statsResult.status === 'rejected') {
        console.warn('Profile stats fetch failed:', statsResult.reason)
      }

      if (activityResult.status === 'rejected') {
        console.warn('Profile activity fetch failed:', activityResult.reason)
      }
    } catch (err) {
      toast.error('Failed to load profile')
      console.error('Profile fetch failed:', err)
    } finally {
      setLoading(false)
    }
  }

  const startEdit = () => {
    setForm({
      displayName: profile?.displayName || '',
      bio: profile?.bio || '',
      jobRole: profile?.jobRole || '',
      skills: (profile?.skills || []).join(', '),
      location: profile?.location || '',
      website: profile?.website || '',
      github: profile?.github || '',
      linkedin: profile?.linkedin || '',
      // New personal-info fields
      phone: profile?.phone || '',
      headline: profile?.headline || '',
      dateOfBirth: profile?.dateOfBirth
        ? new Date(profile.dateOfBirth).toISOString().slice(0, 10)
        : '',
      gender: profile?.gender || '',
      company: profile?.company || '',
      yearsOfExperience:
        profile?.yearsOfExperience != null ? String(profile.yearsOfExperience) : '',
      collegeStudent: !!profile?.collegeStudent,
      openToWork: !!profile?.openToWork,
      languages: (profile?.languages || []).join(', '),
      resumeHeadline: profile?.resumeHeadline || '',
    })
    setEditing(true)
  }

  const cancelEdit = () => setEditing(false)

  // ─── Avatar upload ──────────────────────────────────────────────────────────
  const handleAvatarPick = () => avatarInputRef.current?.click()

  const handleAvatarChange = async (e) => {
    const file = e.target.files?.[0]
    // Always reset the input so the same file can be picked again
    e.target.value = ''
    if (!file) return

    setAvatarUploading(true)
    setAvatarProgress(0)
    const toastId = toast.loading('Uploading avatar…')
    try {
      const url = await uploadAvatar(file, user?.uid, (pct) => setAvatarProgress(pct))
      // Persist the URL on the profile
      const res = await userProfileApi.setMyAvatar(url)
      setProfile(res.profile)
      toast.success('Avatar updated', { id: toastId })
    } catch (err) {
      toast.error(err.message || 'Failed to upload avatar', { id: toastId })
    } finally {
      setAvatarUploading(false)
      setAvatarProgress(0)
    }
  }

  const handleAvatarRemove = async () => {
    setAvatarUploading(true)
    const toastId = toast.loading('Removing avatar…')
    try {
      const res = await userProfileApi.deleteMyAvatar()
      setProfile(res.profile)
      toast.success('Avatar removed', { id: toastId })
    } catch (err) {
      toast.error(err.message || 'Failed to remove avatar', { id: toastId })
    } finally {
      setAvatarUploading(false)
    }
  }
  const isValidWebsite = (url) => {
  if (!url) return true;

  try {
    new URL(url.startsWith("http") ? url : `https://${url}`);
    return true;
  } catch {
    return false;
  }
};

const isValidLinkedIn = (url) => {
  if (!url) return true;

  return /^https?:\/\/(www\.)?linkedin\.com\/in\/.+$/i.test(url);
};

const isValidGithub = (username) => {
  if (!username) return true;

  return /^[a-zA-Z0-9-]+$/.test(username);
};

  const saveEdit = async () => {
    const githubUsername = getGithubUsername(form.github)

    if (!isValidWebsite(form.website.trim())) {
      toast.error("Please enter a valid website URL")
      return
    }

    if (!isValidLinkedIn(form.linkedin.trim())) {
      toast.error("Please enter a valid LinkedIn profile URL")
      return
    }

    if (!isValidGithub(githubUsername)) {
      toast.error("Invalid GitHub username")
      return
    }

    // Validate yearsOfExperience if provided
    const yoeRaw = form.yearsOfExperience.trim()
    let yearsOfExperience = undefined
    if (yoeRaw !== '') {
      const n = Number(yoeRaw)
      if (!Number.isInteger(n) || n < 0 || n > 80) {
        toast.error('Years of experience must be a whole number between 0 and 80')
        return
      }
      yearsOfExperience = n
    }

    setSaving(true)

    try {
      const res = await userProfileApi.updateMyProfile({
        displayName: form.displayName.trim(),
        bio: form.bio.trim(),
        jobRole: form.jobRole.trim(),
        skills: form.skills.split(',').map(s => s.trim()).filter(Boolean),
        location: form.location.trim(),
        website: form.website.trim(),
        github: githubUsername,
        linkedin: form.linkedin.trim(),
        // New personal-info fields
        phone: form.phone.trim(),
        headline: form.headline.trim(),
        dateOfBirth: form.dateOfBirth || null,
        gender: form.gender || '',
        company: form.company.trim(),
        yearsOfExperience,
        collegeStudent: form.collegeStudent,
        openToWork: form.openToWork,
        languages: form.languages.split(',').map(l => l.trim()).filter(Boolean),
        resumeHeadline: form.resumeHeadline.trim(),
      })
      setProfile(res.profile)
      setEditing(false)
      toast.success('Profile updated')
    } catch (err) {
      toast.error(err.message || 'Failed to save profile')
    } finally {
      setSaving(false)
    }
  }

  const displayName =
    profile?.displayName ||
    user?.displayName ||
    user?.email?.split('@')[0] ||
    'User'
  const initials = displayName.charAt(0).toUpperCase()
  const avatarGradient =
    AVATAR_GRADIENTS[(displayName.charCodeAt(0) || 0) % AVATAR_GRADIENTS.length]

  const formatDate = (date) => {
    if (!date) return ''
    return new Date(date).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    })
  }

  const externalHref = (url) =>
    url.startsWith('http') ? url : `https://${url}`

  if (loading) {
    return <SkeletonProfile />
  }

  return (
    <div className="min-h-screen bg-background">
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-0 left-1/4 w-96 h-96 bg-sky-500/5 rounded-full blur-3xl" />
        <div className="absolute bottom-0 right-1/4 w-96 h-96 bg-cyan-500/5 rounded-full blur-3xl" />
      </div>

      <div className="relative max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <motion.div
          variants={containerVariants}
          initial="hidden"
          animate="visible"
          className="space-y-6"
        >
          {/* Profile Header */}
          <motion.div
            variants={itemVariants}
            className="relative overflow-hidden rounded-2xl bg-card/80 backdrop-blur-sm border border-border shadow-[0_8px_30px_rgb(0,0,0,0.06)] hover:shadow-xl hover:border-primary/20 transition-all duration-300 p-6">
            <div className="flex flex-col sm:flex-row items-start gap-5">
             <div className="relative flex-shrink-0 group">
  <div className="w-20 h-20 rounded-3xl overflow-hidden border border-sky-200 bg-gradient-to-br from-sky-100 to-cyan-100 flex items-center justify-center shadow-sm">
    {profile?.avatarUrl ? (
      <img
        src={profile.avatarUrl}
        alt={displayName}
        className="w-full h-full object-cover"
      />
    ) : (
      <span className="text-3xl font-bold bg-gradient-to-br from-sky-500 to-cyan-500 bg-clip-text text-transparent">
        {initials}
      </span>
    )}
  </div>

  {/* Upload progress overlay */}
  {avatarUploading && (
    <div className="absolute inset-0 rounded-3xl bg-background/70 backdrop-blur-sm flex flex-col items-center justify-center">
      <Loader2 className="w-5 h-5 text-sky-500 animate-spin" />
      {avatarProgress > 0 && (
        <span className="text-[10px] font-medium text-sky-600 mt-0.5">{avatarProgress}%</span>
      )}
    </div>
  )}

  {/* Avatar controls — only on own profile */}
  {isOwnProfile && !avatarUploading && (
    <div className="absolute -bottom-1 -right-1 flex gap-1">
      <button
        type="button"
        onClick={handleAvatarPick}
        title="Upload photo"
        className="w-7 h-7 rounded-full bg-sky-500 hover:bg-sky-600 text-white flex items-center justify-center shadow-md ring-2 ring-background transition-colors"
      >
        <Camera className="w-3.5 h-3.5" />
      </button>
      {profile?.avatarUrl && (
        <button
          type="button"
          onClick={handleAvatarRemove}
          title="Remove photo"
          className="w-7 h-7 rounded-full bg-rose-500 hover:bg-rose-600 text-white flex items-center justify-center shadow-md ring-2 ring-background transition-colors"
        >
          <X className="w-3.5 h-3.5" />
        </button>
      )}
    </div>
  )}

  {/* Hidden file input */}
  <input
    ref={avatarInputRef}
    type="file"
    accept="image/jpeg,image/png,image/webp,image/gif"
    onChange={handleAvatarChange}
    className="hidden"
  />
</div>

              <div className="flex-1 min-w-0">
                {editing ? (
                  <div className="mb-0">
                    <Input
                      label="Display Name"
                      name="displayName"
                      value={form.displayName}
                      onChange={(e) =>
                        setForm((f) => ({ ...f, displayName: e.target.value }))
                      }
                      placeholder="Your name"
                    />
                  </div>
                ) : (
                  <>
                    <div className="flex items-center gap-2 flex-wrap">
                      <h1 className="text-2xl font-bold text-foreground">{displayName}</h1>
                      {profile?.openToWork && (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-emerald-500/10 border border-emerald-500/30 text-emerald-500 text-xs font-medium">
                          <Briefcase className="w-3 h-3" />
                          Open to work
                        </span>
                      )}
                      {profile?.collegeStudent && (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-indigo-500/10 border border-indigo-500/30 text-indigo-400 text-xs font-medium">
                          <GraduationCap className="w-3 h-3" />
                          Student
                        </span>
                      )}
                    </div>
                    {(profile?.jobRole || profile?.headline) && (
                      <p className="text-sky-400 font-medium mt-0.5">
                        {profile?.headline || profile.jobRole}
                      </p>
                    )}
                    {profile?.company && (
                      <p className="flex items-center gap-1.5 text-sm text-muted-foreground mt-1">
                        <Briefcase className="w-3.5 h-3.5 flex-shrink-0" />
                        {profile.company}
                      </p>
                    )}
                    {profile?.location && (
                      <p className="flex items-center gap-1.5 text-sm text-muted-foreground mt-1">
                        <MapPin className="w-3.5 h-3.5 flex-shrink-0" />
                        {profile.location}
                      </p>
                    )}
                  </>
                )}
              </div>

              {isOwnProfile && (
                <div className="flex items-center gap-2 self-start">
                  {editing ? (
                    <>
                      <Button
                        variant="ghost"
                        onClick={cancelEdit}
                        disabled={saving}
                        className="!py-2 !px-3"
                      >
                        <X className="w-4 h-4" />
                      </Button>
                      <Button
                        variant="primary"
                        onClick={saveEdit}
                        loading={saving}
                        className="!py-2 !px-4 text-sm"
                      >
                        <Save className="w-4 h-4 mr-1.5" />
                        Save
                      </Button>
                    </>
                  ) : (
                    <Button
                      variant="outline"
                      onClick={startEdit}
                      className="!py-2 !px-4 text-sm"
                    >
                      <Pencil className="w-4 h-4 mr-1.5" />
                      Edit Profile
                    </Button>
                  )}
                </div>
              )}
            </div>

            {/* Bio */}
            <div className="mt-5">
              {editing ? (
                <div>
                 <label className="block text-sm font-medium text-foreground mb-1.5">
                    Bio
                  </label>
                  <textarea
                    value={form.bio}
                    onChange={(e) =>
                      setForm((f) => ({ ...f, bio: e.target.value }))
                    }
                    maxLength={500}
                    rows={3}
                    placeholder="Tell others about yourself..."
                  className="w-full px-4 py-2.5 rounded-lg bg-background border border-border text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-sky-500/50 focus:border-sky-500 resize-none transition-all duration-200"
                  />
                  <p className="text-xs text-sky-200/60 mt-1 text-right">
                    {form.bio.length}/500
                  </p>
                </div>
              ) : profile?.bio ? (
                <p className="text-foreground text-sm leading-relaxed">{profile.bio}</p>
              ) : isOwnProfile ? (
                <p className="text-muted-foreground text-sm italic">
                  No bio yet — click Edit Profile to add one.
                </p>
              ) : null}
            </div>

            {/* Edit extra fields */}
            {editing && (
              <>
              <div className="mt-4 grid sm:grid-cols-2 gap-x-4">
                <Input
                  label="Job Role"
                  name="jobRole"
                  value={form.jobRole}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, jobRole: e.target.value }))
                  }
                  placeholder="e.g. Software Engineer"
                />
                <Input
                  label="Location"
                  name="location"
                  value={form.location}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, location: e.target.value }))
                  }
                  placeholder="e.g. San Francisco, CA"
                />
                <Input
                  label="Skills (comma-separated)"
                  name="skills"
                  value={form.skills}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, skills: e.target.value }))
                  }
                  placeholder="e.g. React, Node.js, Python"
                />
                <Input
                  label="Website"
                  name="website"
                  value={form.website}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, website: e.target.value }))
                  }
                  placeholder="https://yoursite.com"
                />
                <Input
                  label="GitHub Username"
                  name="github"
                  value={form.github}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, github: e.target.value }))
                  }
                  placeholder="username"
                />
                <Input
                  label="LinkedIn URL"
                  name="linkedin"
                  value={form.linkedin}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, linkedin: e.target.value }))
                  }
                  placeholder="https://linkedin.com/in/..."
                />
              </div>

              {/* New personal-info fields */}
              <div className="mt-4 pt-4 border-t border-border">
                <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-3">
                  Personal Info
                </p>
                <div className="grid sm:grid-cols-2 gap-x-4">
