    const daysLeft = isValidDeadline
        ? Math.ceil((deadlineDate - new Date()) / (1000 * 60 * 60 * 24))
        : null
    const isStudent = profile?.role === 'student'
    const canApply = isStudent && profile?.isVerified && challenge.status === 'open' && !applied

    return (
