export default function ConsistencyPanel({ errors = [] }) {
  if (errors.length === 0) return null;

  // Defensive Severity Color Map Configuration
  const severityStyles = {
    error: 'bg-red-500/10 border-red-500/20 text-red-400',
    warning: 'bg-yellow-500/10 border-yellow-500/20 text-yellow-400',
    fallback: 'bg-muted border-border text-muted-foreground'
  };

  return (
    <motion.div 
      initial={{ opacity: 0, y: -10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      className="mb-6 p-4 border border-border bg-card rounded-xl shadow-lg"
    >
      <div className="flex items-center gap-2 mb-3">
        <span className="text-lg font-black bg-foreground text-background px-2 py-0.5 rounded uppercase tracking-tighter">
          Analysis // Flags ({errors.length})
        </span>
      </div>

      <div className="max-h-64 overflow-y-auto space-y-3 pr-1">
        {errors.map((err, idx) => {
          const currentStyle = severityStyles[err.severity] || severityStyles.fallback;

          return (
            <div key={idx} className={`p-3 rounded-lg border text-sm ${currentStyle}`}>
              <p className="font-bold tracking-tight">{err.message}</p>
              {err.offendingText && (
                <blockquote className="mt-1.5 pl-2 border-l-2 border-current italic text-xs opacity-85 line-clamp-2">
                  "{err.offendingText}"
                </blockquote>
              )}
            </div>
          );
        })}
      </div>
    </motion.div>
  );
}

import CryptoJS from 'crypto-js';
import { auth } from '../config/firebase';

const getSecretKey = () => {
  const user = auth?.currentUser;
  // Fallback secret if user is not fully loaded
  return user?.uid || 'fallback_secret_key_teachforplacement';
};

export const encryptKey = (plainTextKey) => {
  if (!plainTextKey) return plainTextKey;
  try {
    const secret = getSecretKey();
    return CryptoJS.AES.encrypt(plainTextKey, secret).toString();
  } catch (error) {
    console.error('Encryption failed:', error);
    return null;
  }
};

export const decryptKey = (cipherText) => {
  if (!cipherText) return cipherText;

  try {
    const secret = getSecretKey();
    const bytes = CryptoJS.AES.decrypt(cipherText, secret);
    const originalText = bytes.toString(CryptoJS.enc.Utf8);

    return originalText || cipherText;
  } catch (error) {
    // If decryption throws, it might be plaintext
    return cipherText;
  }
};

export function getSectionOrderSuggestions({
  experience,
  projects,
  education,
  skills,
}) {
  const suggestions = [];

  const hasExperience = experience.some(
    (e) => e.title?.trim()
  );

  const hasProjects = projects.some(
    (p) => p.name?.trim()
  );

  if (!hasExperience && hasProjects) {
    suggestions.push(
      "Place Projects before Education to highlight practical experience."
    );
  }

  if (hasExperience) {
    suggestions.push(
      "Place Experience immediately after Summary."
    );
  }

  if (skills.trim()) {
    suggestions.push(
      "Place Skills before Projects for better ATS visibility."
    );
  }

  return suggestions;
}

