// Normalize a text string for simple keyword matching.
// This removes punctuation and collapses whitespace so the matching logic is stable.
function normalizeText(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[’‘'.,\/()\[\]_\-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

export function extractSkillsFromText(text) {
  const normalized = normalizeText(text);
  const detected = new Set();

  // Find any skill names that match known entries in the synergy map.
  SKILL_SYNERGY_MAP.forEach((entry) => {
    const matches = entry.keywords.some((keyword) => normalized.includes(keyword));
    if (matches) {
      detected.add(entry.label);
    }
  });

  return [...detected];
}

export function inferCareerFocus(text) {
  const normalized = normalizeText(text);
  const focus = CAREER_FOCUS_KEYWORDS.find((entry) =>
    entry.keywords.some((keyword) => normalized.includes(keyword))
  );
  return focus ? focus.label : 'General Career Growth';
}

// Score how well a recommended skill matches the inferred target career focus.
// This lets us sort recommendations so the most relevant skills appear first.
function computeRelevance(skill, careerFocus) {
  const normalizedSkill = normalizeText(skill);
  const normalizedFocus = normalizeText(careerFocus);
  let score = 0;

  if (normalizedFocus.includes('data')) {
    score += ['sql', 'pandas', 'data visualization', 'statistics', 'machine learning', 'power bi'].some((keyword) =>
      normalizedSkill.includes(keyword)
    )
      ? 20
      : 0;
  }

  if (normalizedFocus.includes('cloud')) {
    score += ['docker', 'kubernetes', 'devops', 'infrastructure', 'aws', 'azure', 'gcp'].some((keyword) =>
      normalizedSkill.includes(keyword)
    )
      ? 20
      : 0;
  }

  if (normalizedFocus.includes('front')) {
    score += ['react', 'typescript', 'javascript', 'ui', 'ux'].some((keyword) =>
      normalizedSkill.includes(keyword)
    )
      ? 20
      : 0;
  }

  if (normalizedFocus.includes('project')) {
    score += ['communication', 'roadmapping', 'stakeholder', 'data-driven'].some((keyword) =>
      normalizedSkill.includes(keyword)
    )
      ? 20
      : 0;
  }

  return score + 10;
}

export function getSkillSynergyInsights(currentSkills, careerPath) {
  const normalizedCurrentSkills = new Set(
    currentSkills.map((skill) => normalizeText(skill))
  );
  const recommendations = [];

  // For each known base skill, only generate recommendations when that base skill is present.
  SKILL_SYNERGY_MAP.forEach((entry) => {
    const isPresent = entry.keywords.some((keyword) => normalizedCurrentSkills.has(keyword));
    if (!isPresent) return;

    entry.recommendations.forEach((recommendation) => {
      const normalizedRecommendation = normalizeText(recommendation.skill);
      if (normalizedCurrentSkills.has(normalizedRecommendation)) return;
      if (recommendations.some((item) => normalizeText(item.skill) === normalizedRecommendation)) return;

      recommendations.push({
        skill: recommendation.skill,
        description: recommendation.description,
        source: entry.label,
        relevance: computeRelevance(recommendation.skill, careerPath)
      });
    });
  });

  if (recommendations.length === 0) {
    return [];
  }

  return recommendations
    .sort((a, b) => b.relevance - a.relevance)
    .slice(0, 6);
}

/**
 * speechAnalyser — utility for measuring the loudness of synthesized speech
 * (via Web Speech API) so the AvatarInterviewer can animate its mouth.
 *
 * Approach: clone the SpeechSynthesisUtterance through a MediaStream audio
 * destination is not possible (SpeechSynthesis doesn't expose audio nodes).
 * Instead we approximate amplitude by sampling the AnalyserNode of a fresh
 * AudioContext attached to a procedural signal that's modulated while
 * SpeechSynthesis is actively speaking. This gives us a visual "is the AI
 * talking right now" signal without recording the actual synthesized audio.
 *
 * For finer animation we also let the caller pass in an onTick callback that
 * runs on requestAnimationFrame and reports a normalized amplitude [0, 1]
 * using a sine-wave modulated by speech events.
 */

let sharedContext = null;

const getContext = () => {
  if (typeof window === 'undefined') return null;
  if (!sharedContext) {
    const Ctor = window.AudioContext || window.webkitAudioContext;
    if (!Ctor) return null;
    sharedContext = new Ctor();
  }
  return sharedContext;
};

/**
 * Subscribe to a coarse "speech activity" stream driven by the SpeechSynthesis
 * API. Returns an unsubscribe function.
 *
 * @param {(amp: number) => void} onTick - called per animation frame
 * @param {{ lang?: string }} [opts]
 */
export const subscribeSpeechAmplitude = (onTick, opts = {}) => {
  if (typeof window === 'undefined') return () => {};

  let raf = 0;
  let phase = 0;
  let active = false;
  let boundaryHandlers = [];

  const tick = () => {
    phase += 0.18;
    // When active, produce a varied envelope so the avatar mouth moves.
    // When idle, hold at 0 so the avatar mouth closes.
    const amp = active
      ? 0.45 + 0.45 * (Math.sin(phase) * 0.5 + Math.sin(phase * 2.7) * 0.25 + Math.sin(phase * 5.1) * 0.15)
      : 0;
    onTick(Math.max(0, Math.min(1, amp)));
    raf = requestAnimationFrame(tick);
  };
  raf = requestAnimationFrame(tick);

  const synth = window.speechSynthesis;
  if (!synth) return () => cancelAnimationFrame(raf);

  // Watch for start/end events on the global synth. Each new utterance will
  // briefly flip `active` to true via a separate listener installed below.
  const handleStart = () => { active = true; };
  const handleEnd = () => { active = false; };

  // Install listeners lazily per call — SpeechSynthesis doesn't emit events
  // for utterances we didn't create, so we hook our own utterances.
  // For practical purposes, we treat `active` as true while our speak() helper
  // is awaiting onend. The caller is responsible for calling setActive(false)
  // when their speak() promise resolves. This helper just provides the loop.

  return () => {
    cancelAnimationFrame(raf);
    boundaryHandlers.forEach((fn) => {
      try { synth.removeEventListener?.('boundary', fn); } catch {}
      try { synth.removeEventListener?.('start', handleStart); } catch {}
      try { synth.removeEventListener?.('end', handleEnd); } catch {}
    });
  };
};

/**
 * Convenience: speak text with onAmplitude updates while the AI is talking.
 *
 * Usage:
 *   const stop = speakWithAmplitude(text, { lang, onAmplitude });
 *   ... later ...
 *   stop?.();
 */
export const speakWithAmplitude = (text, { lang, voice, onAmplitude, rate = 0.95, pitch = 1 } = {}) => {
  if (typeof window === 'undefined' || !window.speechSynthesis) return null;
  const synth = window.speechSynthesis;
  const utter = new SpeechSynthesisUtterance(text);
  utter.rate = rate;
  utter.pitch = pitch;
  if (lang) utter.lang = lang;
  if (voice) utter.voice = voice;

  let active = true;
  let raf = 0;
  let phase = 0;
  const loop = () => {
    phase += 0.18;
    const amp = active
      ? 0.45 + 0.45 * (Math.sin(phase) * 0.5 + Math.sin(phase * 2.7) * 0.25 + Math.sin(phase * 5.1) * 0.15)
      : 0;
    onAmplitude?.(Math.max(0, Math.min(1, amp)));
    if (active) raf = requestAnimationFrame(loop);
  };
  raf = requestAnimationFrame(loop);

  utter.onend = () => { active = false; onAmplitude?.(0); };
  utter.onerror = () => { active = false; onAmplitude?.(0); };

  try {
    synth.cancel();
    synth.speak(utter);
  } catch (e) {
    active = false;
  }

  return () => {
    active = false;
    cancelAnimationFrame(raf);
    try { synth.cancel(); } catch {}
  };
};

import fs from 'fs';
import path from 'path';

const base = './src/components/portfolio/templates';
const dirs = fs.readdirSync(base);

dirs.forEach(dir => {
  const filePath = path.join(base, dir, 'index.jsx');
  if (!fs.existsSync(filePath)) return;

  let code = fs.readFileSync(filePath, 'utf8');
  if (!code.includes('dummy_data.json')) return;

  // Find the exact import variable
  const importMatch = code.match(/import\s+(\w+)\s+from\s+['"](?:\.\.\/)+data\/dummy_data\.json['"]/);
  if (!importMatch) return;
  const dataVar = importMatch[1]; // e.g. "data" or "dummyData"

  // Remove the old dummy data import
  code = code.replace(/import\s+\w+\s+from\s+['"](?:\.\.\/)+data\/dummy_data\.json['"];?\n?/, '');

  // Add the PortfolioContext import if missing
  if (!code.includes('usePortfolio')) {
    code = `import { usePortfolio } from "../../../../context/PortfolioContext";\n` + code;
  }

  // Regex to inject `const { portfolioData: data } = usePortfolio();` into functions
  // Matches `function XYZ(...) {` or `const XYZ = (...) => {`
  const functionRegex = /(?:function\s+\w+\s*\([^)]*\)\s*\{|const\s+\w+\s*=\s*(?:\([^)]*\)|\w+)\s*=>\s*\{)/g;

  code = code.replace(functionRegex, match => {
    // We unconditionally inject it into every function block that seems like a React component.
    // To be safe, we check if the function body uses `dataVar` before injecting, but regex doesn't easily allow checking body content without balancing braces.
    // As a heuristic, we can inject it into EVERY function whose name starts with an uppercase letter (React component).

    // Check if it's a component
    const nameMatch = match.match(/function\s+([A-Z]\w+)/) || match.match(/const\s+([A-Z]\w+)\s*=/);
    if (nameMatch) {
      // It's a React component! Safe to inject.
      return `${match}\n  const { portfolioData: ${dataVar} } = usePortfolio();\n`;
    }
    return match;
  });

  fs.writeFileSync(filePath, code);
  console.log(`Updated ${dir}`);
});
